INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_MILLIONS.M_COUNT_FROM_LEFT', 'MATH.G6.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_MILLIONS', 'Counts places from the left instead of from the ones, so names the wrong place in numbers with different digit counts.', '{"question":"In 4,206,315 which place is the digit 2 in?","wrong_answer":"tens (the second place, counted from the left)","correct_answer":"hundred thousands"}'::jsonb, 'Reads the number like a sentence and numbers the digits in order.', 'Name the place of the same digit in two numbers of different length.', 'Write the number on a place value chart from the ones place leftwards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_MILLIONS.M_ZERO_NOT_A_PLACE', 'MATH.G6.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_MILLIONS', 'Skips a zero when naming places, so the digits after it are placed one too low.', '{"question":"In 3,050,600 which place is the 5 in?","wrong_answer":"hundred thousands (the zero after the 3 was skipped)","correct_answer":"ten thousands"}'::jsonb, 'Treats zero as nothing instead of a place holder.', 'A number with several zeros and a question about the digit after them.', 'Use a place value chart with an empty column filled with 0.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_MILLIONS.M_PLACE_FOR_TOTAL', 'MATH.G6.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_MILLIONS', 'Gives the place name or the digit when asked for the total value.', '{"question":"What is the total value of 7 in 4,370,215?","wrong_answer":"7 (the digit itself)","correct_answer":"70,000"}'::jsonb, 'Place value and total value are used as the same thing.', 'A total value question where the digit is also the answer.', 'Expand the number: 4,000,000 + 300,000 + 70,000 ... and read off the term.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_MILLIONS.M_ZEROS_WRONG_COUNT', 'MATH.G6.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_MILLIONS', 'Writes one zero too many or too few after the digit when working out total value.', '{"question":"Total value of 6 in 2,603,000?","wrong_answer":"60,000","correct_answer":"600,000"}'::jsonb, 'Counts zeros in the number instead of the places to the right of the digit.', 'Distractors ten times larger and ten times smaller.', 'Count the places to the right of the digit on the chart, then write that many zeros.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.SYMBOLS_MILLIONS.M_JOIN_PARTS', 'MATH.G6.NUMBER.WHOLE_NUMBERS.SYMBOLS_MILLIONS', 'Joins the parts as they are said, leaving out the zeros that fill a group of three.', '{"question":"5 million, 40 thousand and 8 in symbols?","wrong_answer":"5,408","correct_answer":"5,040,008"}'::jsonb, 'Does not know that each group after the millions needs three digits.', 'Parts where the thousands group has fewer than three digits.', 'Write each part in its own column group of a place value chart before joining.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.SYMBOLS_MILLIONS.M_MISPLACED_GROUP', 'MATH.G6.NUMBER.WHOLE_NUMBERS.SYMBOLS_MILLIONS', 'Puts the thousands and the units groups in the wrong order.', '{"question":"2 million, 15 thousand and 300 in symbols?","wrong_answer":"2,300,015","correct_answer":"2,015,300"}'::jsonb, 'Writes the smaller group first because it is smaller.', 'An option with the groups swapped.', 'Read the number aloud from the left and tick each group off as it is written.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.READ_WRITE_WORDS_100K.M_HUNDRED_DROPPED', 'MATH.G6.NUMBER.WHOLE_NUMBERS.READ_WRITE_WORDS_100K', 'Leaves out the hundreds word or the word thousand when reading a five-digit number.', '{"question":"Write 45,320 in words.","wrong_answer":"forty-five thousand twenty","correct_answer":"forty-five thousand, three hundred and twenty"}'::jsonb, 'Reads the digits in pairs.', 'Numbers with a hundreds digit and a tens digit.', 'Split the number into thousands and the last three digits, read each, join.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.READ_WRITE_WORDS_100K.M_TEEN_TY_SWAP', 'MATH.G6.NUMBER.WHOLE_NUMBERS.READ_WRITE_WORDS_100K', 'Confuses the teens and the -ty numbers when moving between words and figures.', '{"question":"Write \"thirty thousand and fourteen\" in figures.","wrong_answer":"30,040","correct_answer":"30,014"}'::jsonb, 'Mixes fourteen and forty because they sound alike.', 'Words with a teen and its -ty partner.', 'Say the word slowly: -teen ends with the digit, -ty ends with a zero.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.ORDER_100K.M_FIRST_DIGIT_ONLY', 'MATH.G6.NUMBER.WHOLE_NUMBERS.ORDER_100K', 'Orders numbers by their first digit only, ignoring how many digits each has.', '{"question":"Smallest of 9,840 and 12,305?","wrong_answer":"12,305","correct_answer":"9,840"}'::jsonb, 'Compares from the left without counting digits first.', 'A four-digit number with a bigger first digit than a five-digit number.', 'Count the digits first: more digits means a bigger whole number.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.ORDER_100K.M_LARGEST_FIRST', 'MATH.G6.NUMBER.WHOLE_NUMBERS.ORDER_100K', 'Gives the order from largest to smallest when asked for smallest to largest (or the reverse).', '{"question":"List smallest to largest: 4,080; 40,800; 4,800","wrong_answer":"40,800; 4,800; 4,080","correct_answer":"4,080; 4,800; 40,800"}'::jsonb, 'Does not read the direction word in the question.', 'Items that are marked for the direction.', 'Underline the direction word (ascending, smallest to largest) before ordering.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND.M_ROUND_DOWN_ALWAYS', 'MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND', 'Always drops the hundreds and lower digits to zero, never rounding up.', '{"question":"Round 38,700 to the nearest thousand.","wrong_answer":"38,000","correct_answer":"39,000"}'::jsonb, 'Thinks rounding is cutting off the end of the number.', 'A number whose hundreds digit is 5 or more.', 'Use a number line between two thousands and ask which end is nearer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND.M_WRONG_DIGIT_LOOKED_AT', 'MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND', 'Looks at the tens digit, not the hundreds digit, to decide whether to round up.', '{"question":"Round 24,460 to the nearest thousand.","wrong_answer":"25,000 (looked at 6 in the tens)","correct_answer":"24,000"}'::jsonb, 'Looks at the digit just to the right of the one asked about, taking the wrong place as the one to round to.', 'A number where the hundreds digit is under 5 and the tens digit is 5 or more.', 'Circle the thousands digit, then look only at the next digit to its right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARES_TO_100.M_DOUBLE_NOT_SQUARE', 'MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARES_TO_100', 'Doubles the number instead of multiplying it by itself.', '{"question":"What is 9 squared?","wrong_answer":"18","correct_answer":"81"}'::jsonb, 'Reads the small 2 as "times 2".', 'The doubled answer as a distractor.', 'Draw a 9 by 9 square of dots and count them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARES_TO_100.M_SQUARE_OF_TENS', 'MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARES_TO_100', 'Squares only the non-zero digit, so the square of a multiple of ten has too few zeros.', '{"question":"What is 30 squared?","wrong_answer":"90","correct_answer":"900"}'::jsonb, 'Squares 3 and writes the zero back, or squares 3 and forgets the zero.', 'Squares of multiples of ten with distractors 9 and 90.', 'Write 30 x 30 as 3 tens x 3 tens = 9 hundreds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARE_ROOTS_10000.M_HALVE_NOT_ROOT', 'MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARE_ROOTS_10000', 'Halves the number instead of finding the number that multiplied by itself gives it.', '{"question":"Square root of 64?","wrong_answer":"32","correct_answer":"8"}'::jsonb, 'Confuses square root with half.', 'Half of the number as a distractor.', 'Ask "which number times itself is 64?" and test 8 x 8.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARE_ROOTS_10000.M_ROOT_OF_HUNDREDS', 'MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARE_ROOTS_10000', 'Takes the root of a square ending in zeros as ten times too big or too small.', '{"question":"Square root of 900?","wrong_answer":"90 (the two zeros were kept)","correct_answer":"30"}'::jsonb, 'Does not pair the zeros: two zeros in a square become one zero in the root.', 'Roots of 400, 900 and 6,400 with distractors ten times larger.', 'Square a few multiples of ten and notice the pattern of zeros.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_MILLIONS.M_THOUSANDS_NAMES_SWAPPED', 'MATH.G6.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_MILLIONS', 'Mixes up the ten thousands and the hundred thousands places, so names the digit beside the one asked for.', '{"question":"In 5,374,128 which digit is in the ten thousands place?","wrong_answer":"3","correct_answer":"7"}'::jsonb, 'Both place names end in "thousands"; the child counts inside the thousands group from the left (hundred, ten) the wrong way.', 'An option that is the digit one place to the left of the right one.', 'Label the thousands group on a chart from the right: thousands, ten thousands, hundred thousands, and point at each while saying it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_MILLIONS.M_GROUP_READ_ALONE', 'MATH.G6.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_MILLIONS', 'Reads a group of three digits as a number on its own, so names the place inside the group and leaves out "thousand".', '{"question":"In 4,206,315 which place is the 2 in?","wrong_answer":"hundreds (206 read as its own number)","correct_answer":"hundred thousands"}'::jsonb, 'Sees the commas as breaks between separate numbers and forgets the name of the group.', 'The place name without "thousand" (hundreds, tens) as an option.', 'Read the whole number aloud first: four million, two hundred and six thousand, ... The 2 is in the "two hundred thousand" part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_MILLIONS.M_REST_OF_NUMBER', 'MATH.G6.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_MILLIONS', 'Gives the value of the number from the digit to the end, instead of the digit times its place.', '{"question":"What is the total value of 7 in 4,370,215?","wrong_answer":"70,215","correct_answer":"70,000"}'::jsonb, 'Reads "the value from the 7 onwards" off the number.', 'The tail of the number (the digit and every digit after it) as an option.', 'The total value of one digit has only that digit and zeros: 7 ten thousands is 70,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_MILLIONS.M_EXPANDED_PLACE_SLIP', 'MATH.G6.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_MILLIONS', 'Skips a zero when writing expanded form, so the digits after it get a term one place too small.', '{"question":"Write 3,050,600 in expanded form.","wrong_answer":"3,000,000 + 5,000 + 600","correct_answer":"3,000,000 + 50,000 + 600"}'::jsonb, 'Counts the zeros left in the number instead of the place of each digit.', 'An expanded form whose sum is not the number.', 'Add the terms back up: does 3,000,000 + 5,000 + 600 give 3,050,600? Fix the term that is wrong.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.SYMBOLS_MILLIONS.M_PARTS_WRITTEN_IN_FULL', 'MATH.G6.NUMBER.WHOLE_NUMBERS.SYMBOLS_MILLIONS', 'Writes every part in full with all its zeros, one after the other.', '{"question":"4 million and 6 thousand in symbols?","wrong_answer":"40000006000 (4,000,000 then 6,000 written side by side)","correct_answer":"4,006,000"}'::jsonb, 'Writes each spoken part as a number and joins the pieces instead of placing them in their groups.', 'A string far longer than seven digits as an option.', 'Draw the three groups as boxes of three: millions, thousands, ones. Each part goes in its own box; empty places are 0.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.SYMBOLS_MILLIONS.M_COMMAS_FROM_LEFT', 'MATH.G6.NUMBER.WHOLE_NUMBERS.SYMBOLS_MILLIONS', 'Puts the commas counting from the left, so the groups are wrong.', '{"question":"Write five million, forty thousand and eight in figures, with commas.","wrong_answer":"504,000,8","correct_answer":"5,040,008"}'::jsonb, 'Starts grouping where the writing starts.', 'A number with its commas in the wrong places.', 'Put the commas from the ones end: count three digits from the right, comma, three more, comma.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.READ_WRITE_WORDS_100K.M_ZERO_SAID_AS_WORD', 'MATH.G6.NUMBER.WHOLE_NUMBERS.READ_WRITE_WORDS_100K', 'Reads a zero digit aloud as "zero" or "nought" in the words.', '{"question":"Write 40,506 in words.","wrong_answer":"forty thousand, five hundred and zero six","correct_answer":"forty thousand, five hundred and six"}'::jsonb, 'Reads every digit, zero included, as if spelling the number digit by digit.', 'Words with "zero" in them as an option.', 'A zero is an empty place: it is not said. Cover the 0 and read what is left in each group.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.READ_WRITE_WORDS_100K.M_WORDS_WRITTEN_IN_PIECES', 'MATH.G6.NUMBER.WHOLE_NUMBERS.READ_WRITE_WORDS_100K', 'Writes each word part as figures and joins them, so the number has too many digits.', '{"question":"Write \"sixty thousand and five\" in figures.","wrong_answer":"600005 (60000 then 5)","correct_answer":"60,005"}'::jsonb, 'Writes "sixty thousand" as 60000 and puts the 5 after it instead of in the ones place.', 'A six-digit answer for a five-digit number.', 'Draw five boxes for the places; "sixty thousand" fills the first two, the 5 goes in the ones box, zeros fill the rest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.ORDER_100K.M_SYMBOL_POINTS_TO_BIGGER', 'MATH.G6.NUMBER.WHOLE_NUMBERS.ORDER_100K', 'Uses < and > the wrong way round, reading the symbol as pointing at the bigger number.', '{"question":"Put < or > : 45,302 __ 45,203","wrong_answer":"<","correct_answer":">"}'::jsonb, 'Remembers that the symbol "points" but not which end goes to the bigger number.', 'The reversed symbol as an option.', 'The wide open end faces the bigger number; read 45,302 > 45,203 as "is greater than".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.ORDER_100K.M_ONES_DIGIT_DECIDES', 'MATH.G6.NUMBER.WHOLE_NUMBERS.ORDER_100K', 'When the first digits are the same, decides by the last digit instead of the next place from the left.', '{"question":"Which is larger: 62,815 or 62,951?","wrong_answer":"62,815 (it ends in 5, which is more than 1)","correct_answer":"62,951"}'::jsonb, 'Looks for any digit that is bigger instead of comparing place by place.', 'The number with the bigger ones digit as an option.', 'Go from the left one place at a time and stop at the first place that is different: here the hundreds, 8 against 9.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND.M_ROUND_ZEROS_DROPPED', 'MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND', 'Rounds correctly but writes only the number of thousands.', '{"question":"Round 38,700 to the nearest thousand.","wrong_answer":"39","correct_answer":"39,000"}'::jsonb, 'Thinks the answer is "how many thousands" rather than a number of the same size.', 'The number of thousands without its zeros as an option.', 'A rounded number is still about the same size: 38,700 is about 39,000, not 39.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND.M_NINE_ROUNDED_NO_CARRY', 'MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND', 'Rounds a 9 in the thousands place up to 0 without adding 1 to the ten thousands.', '{"question":"Round 49,600 to the nearest thousand.","wrong_answer":"40,000","correct_answer":"50,000"}'::jsonb, 'Changes the 9 to 0 as in "9 + 1 = 10" but does not carry the 1.', 'The answer with the carry lost as an option.', 'Mark the number line from 49,000 to 50,000: 49,600 is nearer to 50,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND.M_ROUND_IN_STEPS', 'MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND', 'Rounds the number one place at a time from the right, so a number just under halfway is rounded up.', '{"question":"Round 67,449 to the nearest thousand.","wrong_answer":"68,000 (67,449 to 67,450 to 67,500 to 68,000)","correct_answer":"67,000"}'::jsonb, 'Believes rounding is done step by step, each step feeding the next.', 'A rounded-up answer for a number whose hundreds digit is 4.', 'Look only at the hundreds digit once: 4 is less than 5, so round down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARES_TO_100.M_SQUARE_DIGITS_SEPARATELY', 'MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARES_TO_100', 'Squares each digit on its own and writes the results side by side.', '{"question":"What is 23 squared?","wrong_answer":"49 (2 squared is 4, 3 squared is 9)","correct_answer":"529"}'::jsonb, 'Treats squaring like a rule done digit by digit.', 'The digit-by-digit squares as an option.', 'Write 23 x 23 and work it out; check that the answer is between 20 x 20 = 400 and 30 x 30 = 900.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARES_TO_100.M_TENS_SQUARED_PLUS_ONES_SQUARED', 'MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARES_TO_100', 'Squares the tens and the ones and adds them, missing the two middle parts.', '{"question":"What is 21 squared?","wrong_answer":"401 (400 + 1)","correct_answer":"441"}'::jsonb, 'Splits 21 into 20 + 1 and squares each part, as if squaring shared out over adding.', 'The answer that misses 2 x 20 x 1 as an option.', 'Draw the 21 by 21 square split into 20 + 1 each way: there are two strips of 20 as well as the 400 and the 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARE_ROOTS_10000.M_NEAREST_ROOT_ACCEPTED', 'MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARE_ROOTS_10000', 'Gives the nearest whole number as the square root of a number that is not a perfect square.', '{"question":"Is 50 a perfect square?","wrong_answer":"Yes, its square root is 7","correct_answer":"No: 7 x 7 = 49 and 8 x 8 = 64"}'::jsonb, 'Does not check the root by squaring it.', 'A whole-number root for a number that is not a square.', 'Always square the root to check: 7 x 7 is 49, not 50.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARE_ROOTS_10000.M_SIDE_IS_AREA_OVER_FOUR', 'MATH.G6.NUMBER.WHOLE_NUMBERS.SQUARE_ROOTS_10000', 'Divides the area of a square by 4 to find the side, as if it were the perimeter.', '{"question":"A square plot has an area of 144 m2. How long is one side?","wrong_answer":"36 m (144 divided by 4)","correct_answer":"12 m"}'::jsonb, 'Mixes up the area of a square with its perimeter.', 'The area divided by 4 as an option.', 'The side times itself gives the area: which number times itself is 144?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.MULT_4D_BY_2D.M_NO_PLACE_HOLDER_ZERO', 'MATH.G6.NUMBER.MULTIPLICATION.MULT_4D_BY_2D', 'Forgets the zero in the ones place when multiplying by the tens digit, so the second partial product is ten times too small.', '{"question":"2,314 x 23","wrong_answer":"11,570 (the row for the 2 tens was not shifted: 6,942 + 4,628)","correct_answer":"53,222"}'::jsonb, 'Does not remember that the 2 in 23 stands for 20.', 'Distractor with the second row shifted wrongly.', 'Multiply by 3, then by 20 (write the zero first), then add.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.MULT_4D_BY_2D.M_CARRY_ADDED_BEFORE', 'MATH.G6.NUMBER.MULTIPLICATION.MULT_4D_BY_2D', 'Adds the carried digit before multiplying, or forgets it, in a long product.', '{"question":"1,845 x 12","wrong_answer":"22,040 (a carry was lost)","correct_answer":"22,140"}'::jsonb, 'Carries are held in the head and lost.', 'Distractors with one lost carry.', 'Write the carries small above the next digit and cross each one off when used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.MULT_4D_BY_2D.M_MULTIPLY_ONES_ONLY', 'MATH.G6.NUMBER.MULTIPLICATION.MULT_4D_BY_2D', 'Multiplies only by the ones digit of the two-digit number.', '{"question":"1,200 x 15","wrong_answer":"6,000 (x 5 only)","correct_answer":"18,000"}'::jsonb, 'Treats a 2-digit multiplier as a 1-digit one.', 'Answer equal to the product by the ones digit.', 'Break 15 into 10 + 5 and compute both parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10.M_ROUND_ONE_FACTOR', 'MATH.G6.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10', 'Rounds only one of the two factors, so the estimate is not the usual one.', '{"question":"Estimate 38 x 62.","wrong_answer":"40 x 62 = 2,480","correct_answer":"40 x 60 = 2,400"}'::jsonb, 'Thinks rounding one is enough.', 'Distractor from rounding only one factor.', 'Rewrite the question with both numbers rounded before multiplying.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10.M_ZEROS_LOST_IN_ESTIMATE', 'MATH.G6.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10', 'Loses a zero when multiplying the rounded tens, so the estimate is ten times too small.', '{"question":"Estimate 280 x 70.","wrong_answer":"1,960 (the zero of the 70 was lost)","correct_answer":"19,600"}'::jsonb, 'Multiplies 28 x 7 and does not put back both zeros.', 'Estimate with one zero too few.', 'Count the zeros in both factors and put the same number on the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.MULT_PATTERNS.M_ADD_NOT_MULTIPLY', 'MATH.G6.NUMBER.MULTIPLICATION.MULT_PATTERNS', 'Finds an additive rule (the difference between the first two terms) for a multiplying pattern.', '{"question":"2, 6, 18, __: next term?","wrong_answer":"30 (the last gap, 12, was added again)","correct_answer":"54"}'::jsonb, 'Looks at the difference between terms only.', 'Pattern that grows by a growing amount.', 'Divide each term by the one before it and see whether the answer stays the same.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.MULT_PATTERNS.M_CONSTANT_DIFFERENCE', 'MATH.G6.NUMBER.MULTIPLICATION.MULT_PATTERNS', 'Expects the gap between terms to stay the same, so continues a doubling pattern by repeating the last gap.', '{"question":"3, 6, 12, 24, __","wrong_answer":"36 (the last gap, 12, was repeated)","correct_answer":"48"}'::jsonb, 'Has met adding patterns more often than multiplying ones.', 'Next term from repeating the last gap.', 'Write the multiplier above each arrow between the terms.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.MULT_4D_BY_2D.M_COLUMN_BY_COLUMN', 'MATH.G6.NUMBER.MULTIPLICATION.MULT_4D_BY_2D', 'Multiplies each digit only by the digit under it, as in column addition.', '{"question":"1,324 x 12","wrong_answer":"1,328 (4 x 2 and 2 x 1, the rest copied)","correct_answer":"15,888"}'::jsonb, 'Lines the numbers up on the right and works down each column, the way addition is done.', 'An answer about the size of the bigger number as an option.', 'Estimate first: 1,300 x 10 is already 13,000, so 1,328 cannot be right. Then multiply every digit by 2, and every digit by 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.MULT_4D_BY_2D.M_STORY_ADDED', 'MATH.G6.NUMBER.MULTIPLICATION.MULT_4D_BY_2D', 'Adds the two numbers in a story that needs multiplying.', '{"question":"A school buys 24 crates of milk at Ksh 1,350 each. What is the total cost?","wrong_answer":"Ksh 1,374 (1,350 + 24)","correct_answer":"Ksh 32,400"}'::jsonb, 'Reaches for the operation used most often instead of picturing 24 crates each costing 1,350.', 'The sum of the two numbers in the story as an option.', 'Draw the crates: 24 crates each costing 1,350 is 1,350 written 24 times, which is 1,350 x 24.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10.M_EXACT_THEN_ROUNDED', 'MATH.G6.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10', 'Works out the exact product and rounds it, instead of rounding the numbers first.', '{"question":"Estimate 38 x 62 by rounding each number to the nearest ten.","wrong_answer":"2,360 (38 x 62 = 2,356, then rounded)","correct_answer":"40 x 60 = 2,400"}'::jsonb, 'Thinks an estimate is a rounded answer, not a quick answer from rounded numbers.', 'The rounded exact product as an option.', 'An estimate is done in the head before working: round both numbers first, then multiply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10.M_ROUND_TO_HUNDRED', 'MATH.G6.NUMBER.MULTIPLICATION.ESTIMATE_PRODUCT_ROUND10', 'Rounds a three-digit factor to the nearest hundred instead of the nearest ten.', '{"question":"Estimate 236 x 47 by rounding each number to the nearest ten.","wrong_answer":"200 x 50 = 10,000","correct_answer":"240 x 50 = 12,000"}'::jsonb, 'Rounds to the first digit of every number, the way a quick guess is often made.', 'The estimate from rounding to the hundred as an option.', 'Read the place in the question: nearest ten means look at the ones digit only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.MULT_PATTERNS.M_BACKWARDS_MULTIPLIED', 'MATH.G6.NUMBER.MULTIPLICATION.MULT_PATTERNS', 'Multiplies to find a missing term before the given ones, instead of dividing.', '{"question":"__, 24, 72, 216: what is the first term?","wrong_answer":"72 (24 x 3)","correct_answer":"8"}'::jsonb, 'Uses the rule in the forward direction whichever way the gap is.', 'The forward-rule answer for a term at the start.', 'Going back along a times 3 pattern means dividing by 3: 24 / 3 = 8.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.MULTIPLICATION.MULT_PATTERNS.M_NEXT_ROW_ONLY', 'MATH.G6.NUMBER.MULTIPLICATION.MULT_PATTERNS', 'Continues the output column by its gap instead of using the rule on the input.', '{"question":"Inputs 2, 3, 4 give outputs 6, 9, 12. What does input 10 give?","wrong_answer":"15 (added 3 once more)","correct_answer":"30"}'::jsonb, 'Looks down the output column only and treats the table as a list.', 'The next output in the list as the answer for an input far down.', 'Ask what was done to each input: 2 became 6, 3 became 9. Do the same to 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DIVISION.DIV_4D_BY_UP_TO_3D.M_ZERO_IN_QUOTIENT_LOST', 'MATH.G6.NUMBER.DIVISION.DIV_4D_BY_UP_TO_3D', 'Leaves a zero out of the quotient when a digit of the dividend is too small to divide.', '{"question":"3,248 / 8","wrong_answer":"46","correct_answer":"406"}'::jsonb, 'Brings down the next digit and forgets to write 0 in the answer.', 'Dividends such as 3,248 / 8 or 6,030 / 6.', 'Write a 0 in the answer each time a digit cannot be divided.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DIVISION.DIV_4D_BY_UP_TO_3D.M_REMAINDER_AS_PART', 'MATH.G6.NUMBER.DIVISION.DIV_4D_BY_UP_TO_3D', 'Writes the remainder as another digit of the quotient or drops it.', '{"question":"1,000 / 12","wrong_answer":"834 (the remainder 4 written as a digit of the answer)","correct_answer":"83 remainder 4"}'::jsonb, 'Does not know what to do with the leftover.', 'Question where a remainder matters.', 'Check by multiplying back and adding the remainder; it must match the dividend.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DIVISION.DIV_4D_BY_UP_TO_3D.M_DIVIDE_SMALL_BY_BIG', 'MATH.G6.NUMBER.DIVISION.DIV_4D_BY_UP_TO_3D', 'Divides the smaller digit by the larger divisor part the wrong way round (for example 4 by 12 as 12 by 4).', '{"question":"First step of 4,536 / 12","wrong_answer":"12 / 4 = 3 (the divisor divided by the first digit)","correct_answer":"45 / 12 = 3 remainder 9"}'::jsonb, 'Swaps dividend and divisor when the first digit is smaller.', 'Working showing a swapped first step.', 'Use the first digits that make a number at least as big as the divisor.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DIVISION.ESTIMATE_QUOTIENT.M_ROUND_ONLY_DIVIDEND', 'MATH.G6.NUMBER.DIVISION.ESTIMATE_QUOTIENT', 'Rounds the dividend but not the divisor, so the estimate is awkward and usually wrong.', '{"question":"Estimate 4,183 / 21.","wrong_answer":"4,183 / 20 (only the divisor was rounded)","correct_answer":"4,180 / 20 = 209"}'::jsonb, 'Rounds one number only.', 'Estimate from partial rounding.', 'Round both numbers, then divide the rounded numbers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DIVISION.ESTIMATE_QUOTIENT.M_ZEROS_CANCELLED_WRONG', 'MATH.G6.NUMBER.DIVISION.ESTIMATE_QUOTIENT', 'Cancels zeros unevenly when dividing rounded numbers, giving an estimate ten times too large or small.', '{"question":"Estimate 6,300 / 70.","wrong_answer":"9 (one zero too many cancelled)","correct_answer":"90"}'::jsonb, 'Crosses a zero off the top only.', 'Distractors ten times away.', 'Cross the same number of zeros off the dividend and the divisor.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DIVISION.COMBINED_OPERATIONS.M_LEFT_TO_RIGHT_ONLY', 'MATH.G6.NUMBER.DIVISION.COMBINED_OPERATIONS', 'Works strictly from left to right whatever the operations are.', '{"question":"8 + 4 x 5","wrong_answer":"60","correct_answer":"28"}'::jsonb, 'Reads a sum like a sentence.', 'Expression where the left-to-right answer differs.', 'Ask which operation must be done first and underline it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DIVISION.COMBINED_OPERATIONS.M_DIVIDE_AFTER_MULTIPLY', 'MATH.G6.NUMBER.DIVISION.COMBINED_OPERATIONS', 'Always multiplies before dividing, even when the division comes first.', '{"question":"48 / 6 x 2","wrong_answer":"4 (6 x 2 = 12, 48 / 12)","correct_answer":"16"}'::jsonb, 'Believes multiplication ranks above division.', 'Expression with division written before multiplication.', 'Work multiplication and division in the order they appear, left to right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DIVISION.COMBINED_OPERATIONS.M_BRACKET_IGNORED', 'MATH.G6.NUMBER.DIVISION.COMBINED_OPERATIONS', 'Ignores the brackets and works the line in the order written.', '{"question":"4 x (5 + 3)","wrong_answer":"23 (4 x 5, then + 3)","correct_answer":"32"}'::jsonb, 'Reads brackets as decoration.', 'Expression with brackets whose left-to-right value differs.', 'Do what is inside the brackets first; draw a box round it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DIVISION.COMBINED_OPERATIONS.M_SUBTRACT_BEFORE_MULTIPLY', 'MATH.G6.NUMBER.DIVISION.COMBINED_OPERATIONS', 'Subtracts before multiplying when the subtraction comes first in the line.', '{"question":"50 - 4 x 6","wrong_answer":"276","correct_answer":"26"}'::jsonb, 'Does the first operation written.', 'The left-to-right answer as a distractor.', 'Do the multiplication first; use brackets to show the other reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DIVISION.DIV_4D_BY_UP_TO_3D.M_REMAINDER_TOO_BIG', 'MATH.G6.NUMBER.DIVISION.DIV_4D_BY_UP_TO_3D', 'Stops with a remainder as big as the divisor or bigger.', '{"question":"1,000 / 12","wrong_answer":"82 remainder 16","correct_answer":"83 remainder 4"}'::jsonb, 'Takes a quotient digit that is one too small and does not compare the remainder with the divisor.', 'A remainder bigger than the divisor as an option.', 'After each step ask: is what is left smaller than 12? If not, another 12 fits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DIVISION.DIV_4D_BY_UP_TO_3D.M_STORY_REMAINDER_IGNORED', 'MATH.G6.NUMBER.DIVISION.DIV_4D_BY_UP_TO_3D', 'Drops the remainder in a story where it needs one more group.', '{"question":"1,250 learners travel in buses that carry 60 each. How many buses are needed?","wrong_answer":"20","correct_answer":"21 (20 buses carry 1,200, and 50 learners need one more bus)"}'::jsonb, 'Writes the quotient as the answer without asking what the remainder means in the story.', 'The quotient without the extra group as an option.', 'Read the remainder back into the story: 50 learners are still waiting, so they need a bus.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DIVISION.ESTIMATE_QUOTIENT.M_EXACT_THEN_ROUNDED_Q', 'MATH.G6.NUMBER.DIVISION.ESTIMATE_QUOTIENT', 'Divides exactly and rounds the answer, instead of rounding the numbers first.', '{"question":"Estimate 2,396 / 59 by rounding both numbers to the nearest ten.","wrong_answer":"41 (2,396 / 59 = 40.6, rounded)","correct_answer":"2,400 / 60 = 40"}'::jsonb, 'Thinks an estimate is a rounded answer.', 'The rounded exact quotient as an option.', 'Round both numbers first; the estimate should take a few seconds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DIVISION.ESTIMATE_QUOTIENT.M_DIVIDEND_TO_HUNDRED', 'MATH.G6.NUMBER.DIVISION.ESTIMATE_QUOTIENT', 'Rounds the dividend to the nearest hundred instead of the nearest ten.', '{"question":"Estimate 1,438 / 18 by rounding both numbers to the nearest ten.","wrong_answer":"1,400 / 20 = 70","correct_answer":"1,440 / 20 = 72"}'::jsonb, 'Rounds a big number to its front digits out of habit.', 'The estimate from rounding to the hundred as an option.', 'Nearest ten: look at the ones digit only; 1,438 becomes 1,440.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.ADD_FRACTIONS_LCM.M_ADD_ACROSS', 'MATH.G6.NUMBER.FRACTIONS.ADD_FRACTIONS_LCM', 'Adds the numerators and the denominators.', '{"question":"1/2 + 1/3","wrong_answer":"2/5","correct_answer":"5/6"}'::jsonb, 'Treats the fraction bar like a separator between two whole numbers.', 'The across answer as a distractor.', 'Shade 1/2 and 1/3 of the same bar and show the total is more than 1/2, not 2/5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.ADD_FRACTIONS_LCM.M_PRODUCT_NOT_LCM', 'MATH.G6.NUMBER.FRACTIONS.ADD_FRACTIONS_LCM', 'Uses the product of the denominators instead of the LCM, so the answer is correct but not in simplest form, or the child stops early.', '{"question":"1/4 + 1/6","wrong_answer":"10/24 left unsimplified","correct_answer":"5/12"}'::jsonb, 'Does not look for the smallest common multiple.', 'Answer correct in value but not simplest form.', 'List multiples of both denominators and choose the smallest shared one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.ADD_FRACTIONS_LCM.M_RENAME_BOTTOM_ONLY', 'MATH.G6.NUMBER.FRACTIONS.ADD_FRACTIONS_LCM', 'Changes the denominator to the common one but leaves the numerator.', '{"question":"1/3 + 1/4","wrong_answer":"1/12 + 1/12 = 2/12","correct_answer":"7/12"}'::jsonb, 'Remembers "make the bottoms the same" but not "and multiply the top too".', 'Distractor with numerators unchanged.', 'Multiply top and bottom by the same number every time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.SUBTRACT_FRACTIONS_LCM.M_SUBTRACT_ACROSS', 'MATH.G6.NUMBER.FRACTIONS.SUBTRACT_FRACTIONS_LCM', 'Subtracts numerators and subtracts denominators.', '{"question":"3/4 - 1/3","wrong_answer":"2/1","correct_answer":"5/12"}'::jsonb, 'Same across-method as adding.', 'Answer from across subtraction.', 'Rename with the LCM first, then subtract only the numerators.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.SUBTRACT_FRACTIONS_LCM.M_SMALLER_FROM_LARGER_TOP', 'MATH.G6.NUMBER.FRACTIONS.SUBTRACT_FRACTIONS_LCM', 'Subtracts the numerators without first renaming the second fraction with the common denominator.', '{"question":"5/6 - 2/3","wrong_answer":"3/6 (5 - 2 over 6, with 2/3 not renamed)","correct_answer":"1/6"}'::jsonb, 'Subtracts without renaming first.', 'Answer from skipping the rename.', 'Rename both fractions with the common denominator before subtracting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.ADD_MIXED_NUMBERS.M_WHOLE_ONLY_FRACTION_DROPPED', 'MATH.G6.NUMBER.FRACTIONS.ADD_MIXED_NUMBERS', 'Adds the wholes and the fractions but leaves an improper fraction in the answer or drops the extra whole.', '{"question":"1 3/4 + 2 1/2","wrong_answer":"3 5/4","correct_answer":"4 1/4"}'::jsonb, 'Does not rename 5/4 as 1 1/4.', 'Answer with an improper fraction part.', 'After adding, check whether the fraction part is 1 or more; if so, add one to the wholes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.ADD_MIXED_NUMBERS.M_CONVERT_ADD_WHOLE', 'MATH.G6.NUMBER.FRACTIONS.ADD_MIXED_NUMBERS', 'Changes a mixed number to an improper fraction by adding the whole to the numerator.', '{"question":"2 1/3 as an improper fraction","wrong_answer":"3/3 (the whole added to the numerator)","correct_answer":"7/3"}'::jsonb, 'Adds instead of multiplying whole by the denominator.', 'Distractor from adding.', 'Multiply the whole by the denominator, then add the numerator.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.SUBTRACT_MIXED_NUMBERS.M_SMALLER_FROM_LARGER_FRACTION', 'MATH.G6.NUMBER.FRACTIONS.SUBTRACT_MIXED_NUMBERS', 'In 4 1/4 - 2 3/4 subtracts the smaller fraction from the larger (3/4 - 1/4) instead of renaming a whole.', '{"question":"4 1/4 - 2 3/4","wrong_answer":"2 1/2","correct_answer":"1 1/2"}'::jsonb, 'Avoids a subtraction that cannot be done.', 'Answer with the fraction parts swapped.', 'Rename 1 whole as 4/4 so the first fraction becomes 5/4, then subtract.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.SUBTRACT_MIXED_NUMBERS.M_WHOLE_NOT_REDUCED', 'MATH.G6.NUMBER.FRACTIONS.SUBTRACT_MIXED_NUMBERS', 'Renames a whole into the fraction but forgets to take one off the whole number.', '{"question":"5 1/3 - 2 2/3","wrong_answer":"3 2/3","correct_answer":"2 2/3"}'::jsonb, 'Remembers the borrow but not the reduction.', 'Answer one whole too big.', 'Write "5 becomes 4" above the whole when renaming.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.RECIPROCAL.M_NEGATIVE_NOT_FLIP', 'MATH.G6.NUMBER.FRACTIONS.RECIPROCAL', 'Gives the opposite (negative) instead of the reciprocal.', '{"question":"Reciprocal of 3/5","wrong_answer":"-3/5","correct_answer":"5/3"}'::jsonb, 'Confuses the two words that sound like "opposite".', 'Negative option.', 'Multiply the pair; the product must be 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.RECIPROCAL.M_FLIP_ONE_PART', 'MATH.G6.NUMBER.FRACTIONS.RECIPROCAL', 'Flips only the numerator or the denominator, or writes the same fraction.', '{"question":"Reciprocal of 7/9","wrong_answer":"7/7 (only one part turned over)","correct_answer":"9/7"}'::jsonb, 'Is unsure what turning upside down changes.', 'The fraction itself as a distractor.', 'Show 7/9 x 9/7 = 63/63 = 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.SQUARE_OF_FRACTION.M_SQUARE_TOP_ONLY', 'MATH.G6.NUMBER.FRACTIONS.SQUARE_OF_FRACTION', 'Squares the numerator but not the denominator.', '{"question":"(2/5) squared","wrong_answer":"4/5","correct_answer":"4/25"}'::jsonb, 'Thinks the square only applies to the visible top number.', 'Distractor with the denominator unchanged.', 'Write (2/5) x (2/5) and multiply both parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.SQUARE_OF_FRACTION.M_DOUBLE_THE_FRACTION', 'MATH.G6.NUMBER.FRACTIONS.SQUARE_OF_FRACTION', 'Doubles the fraction instead of squaring it.', '{"question":"(3/4) squared","wrong_answer":"6/4 (the fraction doubled)","correct_answer":"9/16"}'::jsonb, 'Reads squared as times 2.', 'Doubling option.', 'Draw a square with side 3/4 and shade the 3 by 3 out of 16 small squares.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.FRACTION_TO_PERCENT.M_DENOMINATOR_AS_PERCENT', 'MATH.G6.NUMBER.FRACTIONS.FRACTION_TO_PERCENT', 'Writes the numerator with a percent sign, ignoring the denominator.', '{"question":"What percentage is 3/5?","wrong_answer":"3%","correct_answer":"60%"}'::jsonb, 'Reads the fraction as a number out of 100.', 'The numerator with % as a distractor.', 'Make the denominator 100: 3/5 = 60/100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.FRACTION_TO_PERCENT.M_COMPARE_NUMERATORS', 'MATH.G6.NUMBER.FRACTIONS.FRACTION_TO_PERCENT', 'Compares two scores out of different totals by their numerators alone.', '{"question":"Which is better: 18 out of 20 or 40 out of 50?","wrong_answer":"40 out of 50","correct_answer":"18 out of 20 (90% against 80%)"}'::jsonb, 'Looks at the bigger number of marks.', 'Pair of marks out of different totals.', 'Convert both marks to percentages before comparing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.PERCENT_TO_FRACTION.M_PERCENT_ONE_OVER', 'MATH.G6.NUMBER.FRACTIONS.PERCENT_TO_FRACTION', 'Writes a percentage as one over that number.', '{"question":"25% as a fraction","wrong_answer":"1/25","correct_answer":"1/4"}'::jsonb, 'Confuses "per cent" with "one in".', 'Distractor of 1 over the number.', 'Write 25% as 25/100 and simplify by dividing top and bottom by 25.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.PERCENT_TO_FRACTION.M_NOT_SIMPLIFIED', 'MATH.G6.NUMBER.FRACTIONS.PERCENT_TO_FRACTION', 'Stops at the fraction out of 100 when asked for the simplest form.', '{"question":"Write 40% in simplest form","wrong_answer":"40/100","correct_answer":"2/5"}'::jsonb, 'Does not see that simplest form is needed.', 'Correct value, not simplest.', 'Divide top and bottom by their highest common factor.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.ADD_FRACTIONS_LCM.M_IMPROPER_LEFT', 'MATH.G6.NUMBER.FRACTIONS.ADD_FRACTIONS_LCM', 'Leaves a sum bigger than 1 as an improper fraction when a mixed number is asked for.', '{"question":"3/4 + 2/3 (as a mixed number)","wrong_answer":"17/12","correct_answer":"1 5/12"}'::jsonb, 'Stops once the fractions are added and does not see that 17/12 is more than one whole.', 'The improper fraction as an option beside the mixed number.', 'Compare the numerator with the denominator: 17 twelfths is 12 twelfths (one whole) and 5 twelfths more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.SUBTRACT_FRACTIONS_LCM.M_BIGGER_DENOMINATOR_BIGGER', 'MATH.G6.NUMBER.FRACTIONS.SUBTRACT_FRACTIONS_LCM', 'Believes the fraction with the bigger denominator is the bigger fraction, so takes the wrong one away.', '{"question":"Which is bigger, 1/3 or 1/4, and by how much?","wrong_answer":"1/4, by 1/12","correct_answer":"1/3, by 1/12"}'::jsonb, 'Reads the denominator like a whole number: 4 is more than 3.', 'The answer with the two fractions the wrong way round.', 'Fold one strip into 3 and one into 4: the more parts, the smaller each part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.SUBTRACT_FRACTIONS_LCM.M_PARTS_NOT_FROM_WHOLE', 'MATH.G6.NUMBER.FRACTIONS.SUBTRACT_FRACTIONS_LCM', 'In a "what is left" story takes one part from the other instead of taking both parts from the whole.', '{"question":"Wanjiru ate 1/4 of a cake and Otieno ate 1/3. What fraction of the cake is left?","wrong_answer":"1/12 (1/3 - 1/4)","correct_answer":"5/12"}'::jsonb, 'Sees two fractions and a "left" question and subtracts one from the other.', 'The difference of the two parts as an option.', 'Draw the cake as 12 pieces: shade 3 for Wanjiru and 4 for Otieno. How many are not shaded?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.ADD_MIXED_NUMBERS.M_ADD_ACROSS_MIXED', 'MATH.G6.NUMBER.FRACTIONS.ADD_MIXED_NUMBERS', 'Adds the wholes, then adds the numerators and the denominators of the fractions.', '{"question":"1 1/2 + 2 1/3","wrong_answer":"3 2/5","correct_answer":"3 5/6"}'::jsonb, 'Carries the adding-across error into mixed numbers.', 'An answer whose fraction part is the numerators and denominators added.', 'Rename the fraction parts to sixths first: 3/6 + 2/6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.ADD_MIXED_NUMBERS.M_WHOLE_ADDED_TO_NUMERATOR', 'MATH.G6.NUMBER.FRACTIONS.ADD_MIXED_NUMBERS', 'Adds a whole number to the numerator of a mixed number.', '{"question":"2 + 1 3/8","wrong_answer":"1 5/8","correct_answer":"3 3/8"}'::jsonb, 'Sees one numerator to add to and adds the whole number there.', 'The answer with the whole number added to the top.', 'Wholes go with wholes: 2 wholes and 1 whole make 3 wholes, the 3/8 stays.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.SUBTRACT_MIXED_NUMBERS.M_WHOLE_MINUS_MIXED', 'MATH.G6.NUMBER.FRACTIONS.SUBTRACT_MIXED_NUMBERS', 'Takes a mixed number from a whole number by taking the wholes and copying the fraction.', '{"question":"5 - 2 3/4","wrong_answer":"3 3/4","correct_answer":"2 1/4"}'::jsonb, 'Has nothing to take the 3/4 from, so writes it down.', 'The answer with the fraction copied as an option.', 'Rename one whole: 5 is 4 4/4. Then 4 4/4 - 2 3/4 = 2 1/4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.SUBTRACT_MIXED_NUMBERS.M_BORROW_TEN', 'MATH.G6.NUMBER.FRACTIONS.SUBTRACT_MIXED_NUMBERS', 'Renames a whole as ten parts, as in subtracting whole numbers, whatever the denominator.', '{"question":"3 1/5 - 1 3/5","wrong_answer":"1 8/5 (the whole renamed as 10 fifths: 11/5 - 3/5)","correct_answer":"1 3/5"}'::jsonb, 'Uses "borrow ten" from column subtraction.', 'An answer from renaming a whole as 10 parts.', 'A whole is as many parts as the denominator: 1 whole is 5 fifths, so 3 1/5 = 2 6/5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.RECIPROCAL.M_ONE_MINUS_FRACTION', 'MATH.G6.NUMBER.FRACTIONS.RECIPROCAL', 'Gives the part that makes the fraction up to one whole instead of the reciprocal.', '{"question":"Reciprocal of 3/5","wrong_answer":"2/5","correct_answer":"5/3"}'::jsonb, 'Mixes up "the number that multiplies to 1" with "the number that adds to 1".', 'The fraction that adds up to 1 as an option.', 'Multiply to check: 3/5 x 2/5 is 6/25, not 1. 3/5 x 5/3 is 15/15 = 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.RECIPROCAL.M_ONE_OVER_NUMERATOR', 'MATH.G6.NUMBER.FRACTIONS.RECIPROCAL', 'Writes 1 over the numerator, copying the rule for whole numbers (the reciprocal of 5 is 1/5).', '{"question":"Reciprocal of 3/5","wrong_answer":"1/3","correct_answer":"5/3"}'::jsonb, 'Learnt the reciprocal of a whole number first and uses the same rule.', 'One over the numerator as an option.', 'A whole number is a fraction over 1: 5 = 5/1, so its reciprocal 1/5 is it turned upside down too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.SQUARE_OF_FRACTION.M_SQUARE_BOTTOM_ONLY', 'MATH.G6.NUMBER.FRACTIONS.SQUARE_OF_FRACTION', 'Squares the denominator but not the numerator.', '{"question":"(2/5) squared","wrong_answer":"2/25","correct_answer":"4/25"}'::jsonb, 'Squares the part that "looks like the number", the bottom.', 'The answer with only the denominator squared.', 'Write it out: 2/5 x 2/5 = (2 x 2)/(5 x 5).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.SQUARE_OF_FRACTION.M_SQUARE_MAKES_BIGGER', 'MATH.G6.NUMBER.FRACTIONS.SQUARE_OF_FRACTION', 'Believes the square of a fraction is bigger than the fraction, as for whole numbers.', '{"question":"Which is bigger: 2/3 or (2/3) squared?","wrong_answer":"(2/3) squared","correct_answer":"2/3 (4/9 is less than 6/9)"}'::jsonb, 'Has only seen squares of whole numbers get bigger.', 'A choice between the fraction and its square.', 'Shade 2/3 of a square, then 2/3 of the shaded part: the second shading is smaller.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.FRACTION_TO_PERCENT.M_ADD_TO_MAKE_100', 'MATH.G6.NUMBER.FRACTIONS.FRACTION_TO_PERCENT', 'Adds the same number to the top and the bottom to make the denominator 100.', '{"question":"7/20 as a percentage","wrong_answer":"87% (7 + 80 over 20 + 80)","correct_answer":"35%"}'::jsonb, 'Makes the denominator 100 by adding, not by multiplying.', 'The answer from adding to top and bottom.', 'Equivalent fractions multiply top and bottom by the same number: 20 x 5 = 100, so 7 x 5 = 35.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.FRACTION_TO_PERCENT.M_DECIMAL_WITH_PERCENT', 'MATH.G6.NUMBER.FRACTIONS.FRACTION_TO_PERCENT', 'Divides the numerator by the denominator and writes the decimal with a percent sign.', '{"question":"3/5 as a percentage","wrong_answer":"0.6%","correct_answer":"60%"}'::jsonb, 'Forgets to multiply by 100 after dividing.', 'The decimal with a percent sign as an option.', 'Per cent means out of 100: 0.6 of the whole is 60 out of 100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.PERCENT_TO_FRACTION.M_OVER_TEN', 'MATH.G6.NUMBER.FRACTIONS.PERCENT_TO_FRACTION', 'Writes a percentage over 10 instead of over 100.', '{"question":"45% as a fraction in simplest form","wrong_answer":"45/10 (4 1/2)","correct_answer":"9/20"}'::jsonb, 'Remembers "over a ten" from decimals.', 'A fraction bigger than 1 for a percentage under 100.', 'Per cent means per hundred: 45% = 45/100, then simplify.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.FRACTIONS.PERCENT_TO_FRACTION.M_SIMPLIFY_UNEVEN', 'MATH.G6.NUMBER.FRACTIONS.PERCENT_TO_FRACTION', 'Divides the numerator and the denominator by different numbers when simplifying.', '{"question":"75% as a fraction in simplest form","wrong_answer":"3/5 (75 / 25 and 100 / 20)","correct_answer":"3/4"}'::jsonb, 'Divides each part by whatever number goes into it.', 'A fraction that is not equal to the percentage.', 'Divide the top and the bottom by the same number: 75 / 25 = 3, 100 / 25 = 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.DECIMAL_PLACES_TEN_THOUSANDTHS.M_PLACE_NAME_SHIFT', 'MATH.G6.NUMBER.DECIMALS.DECIMAL_PLACES_TEN_THOUSANDTHS', 'Names the second place after the point as thousandths, or counts the places one off.', '{"question":"Which place is the 5 in 0.3524?","wrong_answer":"thousandths","correct_answer":"hundredths"}'::jsonb, 'Matches tenths with ten, hundredths with 100 but is unsure about the fourth place.', 'Fourth-place question.', 'Say the names in order: tenths, hundredths, thousandths, ten-thousandths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.DECIMAL_PLACES_TEN_THOUSANDTHS.M_TH_SOUNDS_LIKE_WHOLE', 'MATH.G6.NUMBER.DECIMALS.DECIMAL_PLACES_TEN_THOUSANDTHS', 'Confuses "ten-thousandths" with "thousands" so writes the wrong number of places.', '{"question":"Write 7 ten-thousandths","wrong_answer":"0.007","correct_answer":"0.0007"}'::jsonb, 'Mixes the words for whole-number and decimal places.', 'Distractor with three places.', 'Count four places after the point on a chart and put the 7 in the last.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.ROUND_DECIMALS_3DP.M_DROP_DIGITS', 'MATH.G6.NUMBER.DECIMALS.ROUND_DECIMALS_3DP', 'Cuts the extra digits off without looking at the next digit.', '{"question":"Round 2.3678 to 2 decimal places","wrong_answer":"2.36","correct_answer":"2.37"}'::jsonb, 'Rounding is taken to be truncating.', 'Truncated value as a distractor.', 'Look at the digit after the place you keep.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.ROUND_DECIMALS_3DP.M_NINE_CARRY', 'MATH.G6.NUMBER.DECIMALS.ROUND_DECIMALS_3DP', 'Rounds up a 9 by writing 10 in one place instead of carrying.', '{"question":"Round 4.9976 to 3 decimal places","wrong_answer":"4.9910 (the 10 written in one place)","correct_answer":"4.998"}'::jsonb, 'Does not carry when the digit is 9.', 'Number ending in 9s.', 'Add 1 to the last kept digit and carry as in addition.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_FRACTION.M_DENOMINATOR_TEN_ALWAYS', 'MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_FRACTION', 'Always uses 10 as the denominator whatever the number of decimal places.', '{"question":"0.35 as a fraction","wrong_answer":"35/10","correct_answer":"7/20"}'::jsonb, 'Remembers "tenths" only.', 'Fraction with denominator 10 for a two-place decimal.', 'Count the decimal places: one place is tenths, two is hundredths, three is thousandths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_FRACTION.M_POINT_DROPPED_THEN_ONE', 'MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_FRACTION', 'Writes the digits after the point as a fraction over the number of digits.', '{"question":"0.25 as a fraction","wrong_answer":"25/2","correct_answer":"1/4"}'::jsonb, 'Uses the count of digits as the denominator.', 'Fraction with the digit count as denominator.', 'The denominator is 1 followed by as many zeros as decimal places.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.FRACTION_TO_DECIMAL.M_NUMERATOR_POINT_DENOMINATOR', 'MATH.G6.NUMBER.DECIMALS.FRACTION_TO_DECIMAL', 'Writes the numerator, a point and the denominator as a decimal.', '{"question":"3/4 as a decimal","wrong_answer":"3.4","correct_answer":"0.75"}'::jsonb, 'Treats the bar as a decimal point.', 'The 3.4 style option.', 'Divide 3 by 4 or rename 3/4 as 75/100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.FRACTION_TO_DECIMAL.M_DIVIDE_THE_WRONG_WAY', 'MATH.G6.NUMBER.DECIMALS.FRACTION_TO_DECIMAL', 'Divides the denominator by the numerator.', '{"question":"1/4 as a decimal","wrong_answer":"4","correct_answer":"0.25"}'::jsonb, 'Divides the bigger number by the smaller one.', 'Whole-number answer that is greater than 1 for a proper fraction.', 'A proper fraction is less than 1, so its decimal must be less than 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_PERCENT.M_MOVE_ONE_PLACE', 'MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_PERCENT', 'Moves the decimal point one place, not two.', '{"question":"0.45 as a percentage","wrong_answer":"4.5%","correct_answer":"45%"}'::jsonb, 'Multiplies by 10.', 'Distractor with the point moved once.', 'A percentage is out of 100, so move the point two places right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_PERCENT.M_SMALL_DECIMAL_WRONG', 'MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_PERCENT', 'Writes 0.05 as 50% (or 0.5 as 5%) by losing a zero.', '{"question":"0.05 as a percentage","wrong_answer":"50%","correct_answer":"5%"}'::jsonb, 'Drops the leading zero when moving the point.', 'Decimals with a zero after the point.', 'Put 0.05 on a hundred-square: 5 squares shaded is 5%.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.PERCENT_TO_DECIMAL.M_PERCENT_AS_WHOLE', 'MATH.G6.NUMBER.DECIMALS.PERCENT_TO_DECIMAL', 'Writes the percentage number with a decimal point in front of it only when two digits, or writes 7% as 0.7.', '{"question":"7% as a decimal","wrong_answer":"0.7","correct_answer":"0.07"}'::jsonb, 'Treats % as tenths.', 'Single-digit percentages.', 'Write 7% as 7/100 and then as a decimal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.PERCENT_TO_DECIMAL.M_DIVIDE_BY_TEN', 'MATH.G6.NUMBER.DECIMALS.PERCENT_TO_DECIMAL', 'Divides by 10, not 100.', '{"question":"35% as a decimal","wrong_answer":"3.5","correct_answer":"0.35"}'::jsonb, 'Moves the point one place.', 'Ten times too large.', 'Change to a fraction over 100 first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.ADD_DECIMALS_4DP.M_RIGHT_ALIGN', 'MATH.G6.NUMBER.DECIMALS.ADD_DECIMALS_4DP', 'Lines the digits up on the right instead of lining up the decimal points.', '{"question":"3.5 + 2.125","wrong_answer":"2.160 (35 + 2,125 added as whole numbers)","correct_answer":"5.625"}'::jsonb, 'Aligns the numbers as whole numbers.', 'Numbers with different decimal lengths.', 'Fill every number with zeros so each has 4 places before adding.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.ADD_DECIMALS_4DP.M_CARRY_ACROSS_POINT', 'MATH.G6.NUMBER.DECIMALS.ADD_DECIMALS_4DP', 'Does not carry across the decimal point, or treats the digits after the point as a separate whole number.', '{"question":"0.7500 + 0.4600","wrong_answer":"0.2100 (the 1 was not carried across the point)","correct_answer":"1.2100"}'::jsonb, 'Treats the two sides of the point as separate sums.', 'Sums that carry over the point.', 'Add as whole numbers and put the point straight down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.SUBTRACT_DECIMALS_4DP.M_SMALLER_FROM_LARGER_DIGIT', 'MATH.G6.NUMBER.DECIMALS.SUBTRACT_DECIMALS_4DP', 'Subtracts the smaller digit from the larger in every column, whichever is on top.', '{"question":"5.0000 - 1.2345","wrong_answer":"4.2345 (the smaller digit taken from the bigger in each column)","correct_answer":"3.7655"}'::jsonb, 'Does not rename across zeros.', 'Subtraction from a whole number.', 'Rename tens, hundreds and so on, starting from the right, or use a number line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.SUBTRACT_DECIMALS_4DP.M_UNEQUAL_LENGTH_LEFT', 'MATH.G6.NUMBER.DECIMALS.SUBTRACT_DECIMALS_4DP', 'Subtracts a shorter decimal without writing zeros, so lines up the wrong digits.', '{"question":"2.5 - 0.325","wrong_answer":"2.225 (the empty places were left blank and the 2 and 5 copied down)","correct_answer":"2.175"}'::jsonb, 'Leaves the empty places blank and subtracts the 5 from the 3.', 'Decimals of unequal length.', 'Add zeros so both numbers have the same number of places.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.DECIMAL_PLACES_TEN_THOUSANDTHS.M_ONETHS', 'MATH.G6.NUMBER.DECIMALS.DECIMAL_PLACES_TEN_THOUSANDTHS', 'Names the first place after the point "ones" (or "oneths"), as if the places mirrored round the point, so every place after it is one off.', '{"question":"In 2.0471 which place is the 4 in?","wrong_answer":"tenths","correct_answer":"hundredths"}'::jsonb, 'Believes the places after the point mirror the whole number places, ones included.', 'The place one to the left as an option.', 'The ones place is the middle of the chart; the first place after the point is tenths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.DECIMAL_PLACES_TEN_THOUSANDTHS.M_ZERO_AFTER_POINT_SKIPPED', 'MATH.G6.NUMBER.DECIMALS.DECIMAL_PLACES_TEN_THOUSANDTHS', 'Skips a zero just after the point, so names the later digits one place too high.', '{"question":"In 0.0306 which place is the 6 in?","wrong_answer":"thousandths","correct_answer":"ten-thousandths"}'::jsonb, 'Treats zeros after the point as empty and starts counting at the first digit that is not zero.', 'The place one too high as an option.', 'Write the number on the chart: every digit after the point, zeros too, has its own column.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.ROUND_DECIMALS_3DP.M_ROUND_TO_WRONG_PLACES', 'MATH.G6.NUMBER.DECIMALS.ROUND_DECIMALS_3DP', 'Rounds to the wrong number of decimal places.', '{"question":"Round 6.4283 to 3 decimal places.","wrong_answer":"6.43","correct_answer":"6.428"}'::jsonb, 'Counts the places in the answer wrongly, or counts from the end of the number.', 'The answer rounded to one place fewer as an option.', 'Count three digits after the point, draw a line, then look at the next digit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.ROUND_DECIMALS_3DP.M_ROUND_IN_STEPS_DECIMAL', 'MATH.G6.NUMBER.DECIMALS.ROUND_DECIMALS_3DP', 'Rounds from the right one place at a time, so a digit that should round down is pushed up.', '{"question":"Round 3.4449 to 2 decimal places.","wrong_answer":"3.45 (3.4449 to 3.445 to 3.45)","correct_answer":"3.44"}'::jsonb, 'Believes each rounding step feeds the next.', 'The rounded-up answer as an option.', 'Look once at the digit after the place you round to: here 4, so round down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_FRACTION.M_DECIMAL_FRACTION_NOT_SIMPLIFIED', 'MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_FRACTION', 'Writes the decimal over 10, 100 or 1,000 but does not simplify when the simplest form is asked.', '{"question":"0.35 as a fraction in simplest form","wrong_answer":"35/100","correct_answer":"7/20"}'::jsonb, 'Stops at the first fraction.', 'The unsimplified fraction as an option.', 'Divide the top and the bottom by the same number until nothing else divides both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_FRACTION.M_WHOLE_PART_DROPPED', 'MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_FRACTION', 'Drops the whole number part when changing a decimal more than 1 to a fraction.', '{"question":"2.6 as a mixed number in simplest form","wrong_answer":"3/5","correct_answer":"2 3/5"}'::jsonb, 'Looks only at the digits after the point.', 'The fraction part alone as an option.', 'Read 2.6 aloud: two and six tenths. The two wholes stay.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.FRACTION_TO_DECIMAL.M_HUNDREDTHS_AS_TENTHS', 'MATH.G6.NUMBER.DECIMALS.FRACTION_TO_DECIMAL', 'Writes hundredths in the tenths place.', '{"question":"7/100 as a decimal","wrong_answer":"0.7","correct_answer":"0.07"}'::jsonb, 'Writes the numerator straight after the point whatever the denominator.', 'The answer ten times too big as an option.', 'Hundredths fill two places after the point: 7 hundredths is 0.07.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.FRACTION_TO_DECIMAL.M_SCALE_BOTTOM_ONLY', 'MATH.G6.NUMBER.DECIMALS.FRACTION_TO_DECIMAL', 'Makes the denominator 100 but leaves the numerator as it was.', '{"question":"3/20 as a decimal","wrong_answer":"0.03 (3 over 100)","correct_answer":"0.15"}'::jsonb, 'Changes the denominator to a power of ten and forgets the numerator.', 'An answer that is far too small as an option.', 'Multiply the top and the bottom by the same number: 3/20 = 15/100 = 0.15.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_PERCENT.M_PERCENT_SIGN_ONLY', 'MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_PERCENT', 'Puts a percent sign on the decimal without multiplying by 100.', '{"question":"0.45 as a percentage","wrong_answer":"0.45%","correct_answer":"45%"}'::jsonb, 'Thinks a percentage is a decimal with a sign.', 'The decimal with a percent sign as an option.', 'Ask: is 0.45 of the whole less than half or less than one hundredth?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_PERCENT.M_PERCENT_CAPPED_AT_100', 'MATH.G6.NUMBER.DECIMALS.DECIMAL_TO_PERCENT', 'Drops the whole number part, believing a percentage cannot be more than 100.', '{"question":"1.35 as a percentage","wrong_answer":"35%","correct_answer":"135%"}'::jsonb, 'Has only seen percentages of a part of something.', 'The answer with the whole lost as an option.', 'One whole is 100%; 1.35 is one whole and 35 hundredths, so 135%.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.PERCENT_TO_DECIMAL.M_HALF_PERCENT', 'MATH.G6.NUMBER.DECIMALS.PERCENT_TO_DECIMAL', 'Writes a percentage less than 1 with the point moved only one place, or as if it were whole.', '{"question":"0.5% as a decimal","wrong_answer":"0.05","correct_answer":"0.005"}'::jsonb, 'Does not move the point two places when the percentage already has a point.', 'The answer ten times too big as an option.', 'Divide by 100 by moving every digit two places right: 0.5 becomes 0.005.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.PERCENT_TO_DECIMAL.M_OVER_100_PERCENT_DECIMAL', 'MATH.G6.NUMBER.DECIMALS.PERCENT_TO_DECIMAL', 'Puts the point in front of every percentage, so a percentage over 100 becomes less than 1.', '{"question":"120% as a decimal","wrong_answer":"0.120","correct_answer":"1.2"}'::jsonb, 'Thinks every percentage turns into a decimal starting 0.', 'An answer below 1 for a percentage above 100.', '100% is 1 whole, so 120% is more than 1: 1.2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.ADD_DECIMALS_4DP.M_WHOLE_NUMBER_UNDER_DECIMALS', 'MATH.G6.NUMBER.DECIMALS.ADD_DECIMALS_4DP', 'Writes a whole number under the decimal places when adding it to a decimal.', '{"question":"4 + 0.275","wrong_answer":"0.279","correct_answer":"4.275"}'::jsonb, 'Lines up a whole number on the right, as if its point were missing.', 'An answer with the whole number added to the last decimal digit.', 'A whole number has its point after the ones: 4 = 4.000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.ADD_DECIMALS_4DP.M_COLUMN_TOTALS_WRITTEN', 'MATH.G6.NUMBER.DECIMALS.ADD_DECIMALS_4DP', 'Writes the full total of each column instead of carrying.', '{"question":"0.47 + 0.85","wrong_answer":"0.1212 (7 + 5 = 12 and 4 + 8 = 12, written side by side)","correct_answer":"1.32"}'::jsonb, 'Does not carry the ten into the next place.', 'An answer with two-digit column totals as an option.', 'Each place holds one digit: 12 hundredths is 1 tenth and 2 hundredths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.SUBTRACT_DECIMALS_4DP.M_WHOLE_MINUS_DECIMAL_COPIED', 'MATH.G6.NUMBER.DECIMALS.SUBTRACT_DECIMALS_4DP', 'Takes a decimal from a whole number by copying the decimal digits down.', '{"question":"6 - 2.45","wrong_answer":"4.45","correct_answer":"3.55"}'::jsonb, 'Sees nothing to take the .45 from and writes it down.', 'The answer with the decimal digits copied as an option.', 'Write 6 as 6.00, then rename across the zeros.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.DECIMALS.SUBTRACT_DECIMALS_4DP.M_ZEROS_NOT_NINES', 'MATH.G6.NUMBER.DECIMALS.SUBTRACT_DECIMALS_4DP', 'Renames across zeros by making each zero 10 without taking 1 from it, so the answer is too big.', '{"question":"5.0000 - 1.2345","wrong_answer":"3.8765","correct_answer":"3.7655"}'::jsonb, 'Each zero "borrows" ten, but none of them gives one away.', 'The answer from renaming every zero as 10.', 'Rename 5 ones as 4 ones, 9 tenths, 9 hundredths, 9 thousandths and 10 ten-thousandths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.FORM_INEQUALITY.M_AT_LEAST_STRICT', 'MATH.G6.NUMBER.INEQUALITIES.FORM_INEQUALITY', 'Writes "at least" as greater than, leaving out the equal case.', '{"question":"\"At least 30 learners\" as an inequality","wrong_answer":"x > 30","correct_answer":"x >= 30"}'::jsonb, 'Does not know that "at least" includes the number itself.', 'Option with > for at least.', 'Ask: can the number of learners be exactly 30? If yes the symbol includes equal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.FORM_INEQUALITY.M_SYMBOL_DIRECTION', 'MATH.G6.NUMBER.INEQUALITIES.FORM_INEQUALITY', 'Writes the symbol pointing the wrong way for "less than" or "more than".', '{"question":"\"Fewer than 12 mandazi\"","wrong_answer":"x > 12","correct_answer":"x < 12"}'::jsonb, 'Confuses the open and the pointed end of the symbol.', 'Reversed symbol.', 'The small end points to the smaller number.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.SIMPLIFY_INEQUALITY.M_FLIP_THE_SYMBOL_FOR_NOTHING', 'MATH.G6.NUMBER.INEQUALITIES.SIMPLIFY_INEQUALITY', 'Reverses the symbol when adding, subtracting or dividing by a positive number.', '{"question":"Simplify x + 4 < 10","wrong_answer":"x > 6","correct_answer":"x < 6"}'::jsonb, 'Has heard that the symbol sometimes flips and applies it every time.', 'Reversed symbol after a one-step change.', 'Test a number: 2 + 4 is less than 10, so x = 2 fits x < 6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.SIMPLIFY_INEQUALITY.M_OPERATION_NOT_INVERTED', 'MATH.G6.NUMBER.INEQUALITIES.SIMPLIFY_INEQUALITY', 'Does the same operation as the one shown instead of the inverse.', '{"question":"Simplify x + 5 < 12","wrong_answer":"x < 17","correct_answer":"x < 7"}'::jsonb, 'Adds 5 to both sides.', 'Answer from the wrong operation.', 'Undo the operation: the inverse of adding is subtracting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.SOLVE_INEQUALITY.M_BOUNDARY_INCLUDED', 'MATH.G6.NUMBER.INEQUALITIES.SOLVE_INEQUALITY', 'Includes the boundary number in a strict inequality.', '{"question":"Largest whole number with x < 8","wrong_answer":"8","correct_answer":"7"}'::jsonb, 'Takes the boundary as part of the answer.', 'Boundary as a distractor.', 'Test 8 in the inequality: 8 < 8 is false.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.SOLVE_INEQUALITY.M_ONE_SOLUTION_ONLY', 'MATH.G6.NUMBER.INEQUALITIES.SOLVE_INEQUALITY', 'Gives a single value as the solution rather than the set of values.', '{"question":"Solutions of x > 4 among 3, 4, 5, 6","wrong_answer":"5 only","correct_answer":"5 and 6"}'::jsonb, 'Solving an equation is taken to give one answer.', 'Question asking how many whole numbers fit.', 'List several numbers and test each; many fit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.SOLVE_INEQUALITY.M_COUNT_ENDS_WRONG', 'MATH.G6.NUMBER.INEQUALITIES.SOLVE_INEQUALITY', 'Counts the whole numbers between two boundaries wrongly by including one end that is not allowed.', '{"question":"How many whole numbers satisfy 3 < x < 8?","wrong_answer":"6","correct_answer":"4"}'::jsonb, 'Counts from 3 to 8 inclusive.', 'Counting question with strict ends.', 'Cross off the boundaries before counting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.FORM_INEQUALITY.M_AT_MOST_AS_MORE', 'MATH.G6.NUMBER.INEQUALITIES.FORM_INEQUALITY', 'Writes "at most" with a greater-than symbol because "most" sounds like "more".', '{"question":"\"A matatu carries at most 14 passengers\" as an inequality","wrong_answer":"x >= 14","correct_answer":"x <= 14"}'::jsonb, 'Matches the word "most" to "more" instead of to the biggest allowed number.', 'The reversed symbol for "at most".', 'Say it as a limit: "at most 14" means 14 or fewer. Mark 14 and shade to the left on a number line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.FORM_INEQUALITY.M_EQUALS_FOR_LIMIT', 'MATH.G6.NUMBER.INEQUALITIES.FORM_INEQUALITY', 'Writes an equation for a limit, as if the number had to be exact.', '{"question":"\"A lift carries no more than 8 people\" as an inequality","wrong_answer":"x = 8","correct_answer":"x <= 8"}'::jsonb, 'Has written equations more often than inequalities, so writes = when a number appears.', 'The equation as an option.', 'Ask: could 5 people be in the lift? If yes, the number is not exactly 8.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.SIMPLIFY_INEQUALITY.M_ONE_SIDE_ONLY', 'MATH.G6.NUMBER.INEQUALITIES.SIMPLIFY_INEQUALITY', 'Does the operation to one side only.', '{"question":"Simplify 3x > 18","wrong_answer":"x > 18","correct_answer":"x > 6"}'::jsonb, 'Removes the 3 from the x side but leaves the other side as it was.', 'The answer with the number side unchanged.', 'Whatever is done to one side is done to the other, as on a balance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.SIMPLIFY_INEQUALITY.M_SYMBOL_BECOMES_EQUALS', 'MATH.G6.NUMBER.INEQUALITIES.SIMPLIFY_INEQUALITY', 'Writes an equals sign in the answer, turning the inequality into an equation.', '{"question":"Simplify x + 5 < 12","wrong_answer":"x = 7","correct_answer":"x < 7"}'::jsonb, 'Copies the steps of solving an equation, including the = sign.', 'The equation as an option.', 'Copy the symbol down on every line: the answer is still "less than".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.SOLVE_INEQUALITY.M_BOUNDARY_LEFT_OUT', 'MATH.G6.NUMBER.INEQUALITIES.SOLVE_INEQUALITY', 'Leaves the boundary out when the inequality allows it (at least, at most).', '{"question":"Smallest whole number with x >= 9","wrong_answer":"10","correct_answer":"9"}'::jsonb, 'Treats every inequality as strict.', 'The next whole number after the boundary as the answer.', 'Read the line under the symbol as "or equal to": 9 is allowed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.NUMBER.INEQUALITIES.SOLVE_INEQUALITY.M_DIVIDE_BEFORE_SUBTRACT', 'MATH.G6.NUMBER.INEQUALITIES.SOLVE_INEQUALITY', 'In a two-step inequality divides only the x term first, so the number added is left as it was.', '{"question":"Solve 2x + 4 < 20","wrong_answer":"x < 6 (2x + 4 < 20 turned into x + 4 < 10)","correct_answer":"x < 8"}'::jsonb, 'Divides the 2x and the 20 but not the 4, or undoes the steps in the wrong order.', 'The answer from dividing before subtracting as an option.', 'Undo the adding first: take 4 from both sides, then divide both sides by 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.MM_AS_UNIT.M_UNIT_TOO_BIG', 'MATH.G6.MEASUR.LENGTH.MM_AS_UNIT', 'Chooses cm or m for the thickness of a coin or wire.', '{"question":"Best unit for the thickness of a one-shilling coin?","wrong_answer":"centimetres","correct_answer":"millimetres"}'::jsonb, 'Uses the unit met most often.', 'A tiny object with cm as an option.', 'Hold a ruler to a coin and read the nearest mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.MM_AS_UNIT.M_RULER_COUNT_FROM_ONE', 'MATH.G6.MEASUR.LENGTH.MM_AS_UNIT', 'Reads a length on a ruler from the 1 mark instead of from 0, so is out by one mm or cm.', '{"question":"An eraser starts at 0 and ends on the 4th small mark after 3 cm","wrong_answer":"3 cm 5 mm","correct_answer":"3 cm 4 mm"}'::jsonb, 'Counts the marks, not the spaces.', 'Reading one mm too large.', 'Count the spaces between the marks, starting from zero.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.MM_CM_RELATIONSHIP.M_HUNDRED_NOT_TEN', 'MATH.G6.MEASUR.LENGTH.MM_CM_RELATIONSHIP', 'Believes 1 cm is 100 mm (as 1 m is 100 cm).', '{"question":"How many mm in 3 cm?","wrong_answer":"300 mm","correct_answer":"30 mm"}'::jsonb, 'Carries the metre-centimetre relationship over.', 'Answers 100 times larger.', 'Count the small marks in one cm on a ruler.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.MM_CM_RELATIONSHIP.M_MM_AS_DECIMAL_CM', 'MATH.G6.MEASUR.LENGTH.MM_CM_RELATIONSHIP', 'Writes 25 mm as 2.5 cm and then reads it as 2 cm 5 mm in the wrong way round, or as 25 cm.', '{"question":"25 mm in cm and mm","wrong_answer":"25 cm (the unit was not changed)","correct_answer":"2 cm 5 mm"}'::jsonb, 'Does not see mm and cm as separate units.', 'Option with the unit swapped.', 'Group the mm into tens: each ten mm is one cm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.CONVERT_TO_MM.M_ADD_NOT_MULTIPLY', 'MATH.G6.MEASUR.LENGTH.CONVERT_TO_MM', 'Adds the cm to the mm without changing the cm to mm.', '{"question":"4 cm 7 mm in mm","wrong_answer":"11 mm","correct_answer":"47 mm"}'::jsonb, 'Does not change the unit of the cm.', 'The added value.', 'Change the cm to mm first (x 10), then add the mm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.CONVERT_TO_MM.M_TIMES_HUNDRED', 'MATH.G6.MEASUR.LENGTH.CONVERT_TO_MM', 'Multiplies the cm by 100.', '{"question":"6 cm in mm","wrong_answer":"600 mm","correct_answer":"60 mm"}'::jsonb, 'Mixes up 10 and 100.', 'Ten times too large.', 'Use 10 small marks per cm on the ruler.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.ADD_CM_MM.M_MM_OVER_NINE_LEFT', 'MATH.G6.MEASUR.LENGTH.ADD_CM_MM', 'Leaves 10 or more mm in the mm column, so writes an answer such as 5 cm 14 mm.', '{"question":"3 cm 8 mm + 1 cm 6 mm","wrong_answer":"4 cm 14 mm","correct_answer":"5 cm 4 mm"}'::jsonb, 'Does not rename 10 mm as 1 cm.', 'Answer with mm of 10 or over.', 'After adding, rename every 10 mm as 1 cm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.ADD_CM_MM.M_ADD_AS_DECIMAL', 'MATH.G6.MEASUR.LENGTH.ADD_CM_MM', 'Adds the numbers as decimals (3.8 + 1.6 = 5.4) and reads the answer as 5 cm 4 mm without noticing the renaming.', '{"question":"2 cm 7 mm + 2 cm 5 mm","wrong_answer":"4.12 cm (the mm total 7 + 5 = 12 written after the point)","correct_answer":"5 cm 2 mm"}'::jsonb, 'Reads cm and mm as a decimal.', 'Decimal-style total.', 'Keep cm and mm in separate columns.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.SUBTRACT_CM_MM.M_SMALLER_FROM_LARGER_MM', 'MATH.G6.MEASUR.LENGTH.SUBTRACT_CM_MM', 'Takes the smaller mm number from the larger whatever their order.', '{"question":"5 cm 2 mm - 2 cm 7 mm","wrong_answer":"3 cm 5 mm","correct_answer":"2 cm 5 mm"}'::jsonb, 'Avoids renaming.', 'Reverse-subtraction mm part.', 'Rename 1 cm as 10 mm so the mm part becomes 12.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.SUBTRACT_CM_MM.M_RENAME_NOT_REDUCED', 'MATH.G6.MEASUR.LENGTH.SUBTRACT_CM_MM', 'Adds 10 mm but does not take 1 cm off the cm column.', '{"question":"6 cm 3 mm - 2 cm 8 mm","wrong_answer":"4 cm 5 mm","correct_answer":"3 cm 5 mm"}'::jsonb, 'Forgets the second half of renaming.', 'Answer one cm too large.', 'Write "6 becomes 5" above the cm when renaming.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.MULTIPLY_CM_MM.M_MULTIPLY_CM_ONLY', 'MATH.G6.MEASUR.LENGTH.MULTIPLY_CM_MM', 'Multiplies the cm and leaves the mm unchanged.', '{"question":"2 cm 4 mm x 3","wrong_answer":"6 cm 4 mm","correct_answer":"7 cm 2 mm"}'::jsonb, 'Treats the mm as a label.', 'Answer with mm not multiplied.', 'Multiply both parts, then rename.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.MULTIPLY_CM_MM.M_MM_NOT_RENAMED_AFTER_MULT', 'MATH.G6.MEASUR.LENGTH.MULTIPLY_CM_MM', 'Leaves the product of the mm above 9 in the mm column.', '{"question":"3 cm 6 mm x 4","wrong_answer":"12 cm 24 mm","correct_answer":"14 cm 4 mm"}'::jsonb, 'Does not rename after multiplying.', 'Answer with mm of 10 or more.', 'After multiplying rename every ten mm as one cm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.DIVIDE_CM_MM.M_REMAINDER_CM_LOST', 'MATH.G6.MEASUR.LENGTH.DIVIDE_CM_MM', 'Divides the cm and the mm separately and loses the remainder of the cm.', '{"question":"7 cm 2 mm / 4","wrong_answer":"1 cm 0 mm (7 / 4 and 2 / 4 divided separately)","correct_answer":"1 cm 8 mm"}'::jsonb, 'Does not convert the leftover cm to mm.', 'Answer from dividing parts separately.', 'Change the whole length to mm and divide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_PRACTICAL.M_CIRCUMFERENCE_AS_DIAMETER', 'MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_PRACTICAL', 'Reads the diameter from the table where the circumference is wanted.', '{"question":"A drum is 35 cm across; length of string round it?","wrong_answer":"35 cm","correct_answer":"110 cm"}'::jsonb, 'Does not see which column is which.', 'The given length as an option.', 'Mark with a finger the distance across and the distance round on a real tin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_PRACTICAL.M_TURNS_NOT_USED', 'MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_PRACTICAL', 'Gives the distance for one turn of a wheel when asked for many turns.', '{"question":"Wheel of circumference 2 m turns 50 times","wrong_answer":"2 m","correct_answer":"100 m"}'::jsonb, 'Does not multiply by the number of turns.', 'One-turn distance as an option.', 'Draw 3 turns on a line and count the lengths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_DIAMETER_RELATION.M_RADIUS_FOR_DIAMETER', 'MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_DIAMETER_RELATION', 'Uses the radius where the diameter is needed (or the reverse).', '{"question":"Radius 7 cm; circumference with pi = 22/7?","wrong_answer":"22 cm","correct_answer":"44 cm"}'::jsonb, 'Does not double the radius.', 'Half the correct value.', 'Draw the radius and the diameter on a circle and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_DIAMETER_RELATION.M_CIRCUMFERENCE_TWICE_DIAMETER', 'MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_DIAMETER_RELATION', 'Believes the circumference is twice the diameter.', '{"question":"Diameter 10 cm; circumference about?","wrong_answer":"20 cm","correct_answer":"31 cm"}'::jsonb, 'Compares the distance round with two diameters.', 'Option equal to twice the diameter.', 'Roll a tin along a ruler for one turn and compare with its width.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.MM_AS_UNIT.M_CM_MARKS_ADDED', 'MATH.G6.MEASUR.LENGTH.MM_AS_UNIT', 'Adds the whole centimetres and the small marks instead of reading cm and mm separately.', '{"question":"A lead ends 3 small marks after the 5 cm mark: length in mm?","wrong_answer":"8 mm (5 + 3)","correct_answer":"53 mm"}'::jsonb, 'Counts every number on the ruler as the same kind of unit.', 'The sum of the cm and the marks as an option.', 'Say it with units: 5 cm and 3 mm, then change the cm to mm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.ADD_CM_MM.M_CARRY_FORGOTTEN', 'MATH.G6.MEASUR.LENGTH.ADD_CM_MM', 'Renames 10 mm as 1 cm but does not add that cm to the total.', '{"question":"3 cm 8 mm + 1 cm 6 mm","wrong_answer":"4 cm 4 mm","correct_answer":"5 cm 4 mm"}'::jsonb, 'Takes ten mm off the mm column and forgets where it goes.', 'Total that is one cm short.', 'Write the new cm above the cm column when renaming.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.DIVIDE_CM_MM.M_UNIT_NOT_CHANGED_BACK', 'MATH.G6.MEASUR.LENGTH.DIVIDE_CM_MM', 'Divides correctly in mm but gives the answer in cm, or the reverse.', '{"question":"A 5 cm 6 mm rod cut into 4 equal pieces: length of each in mm?","wrong_answer":"1.4 (cm)","correct_answer":"14 mm"}'::jsonb, 'Does not look at the unit the question asks for.', 'Answer that is ten times too small.', 'Underline the unit in the question before writing the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.MM_AS_UNIT.M_OBJECT_NOT_AT_ZERO', 'MATH.G6.MEASUR.LENGTH.MM_AS_UNIT', 'Reads the mark at the end of the object as its length when the object does not start at 0.', '{"question":"A nail lies from the 2 cm mark to the 7 cm 3 mm mark. How long is it?","wrong_answer":"7 cm 3 mm","correct_answer":"5 cm 3 mm (53 mm)"}'::jsonb, 'Thinks the ruler reading is always the length, wherever the object starts.', 'The end reading as an option.', 'Count the cm and mm from the start of the nail to its end, or take the start reading from the end reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.MM_CM_RELATIONSHIP.M_MM_BIGGER_THAN_CM', 'MATH.G6.MEASUR.LENGTH.MM_CM_RELATIONSHIP', 'Thinks a length in mm is longer because its number is bigger.', '{"question":"Which is longer: 8 mm or 2 cm?","wrong_answer":"8 mm","correct_answer":"2 cm (20 mm)"}'::jsonb, 'Compares the numbers and not the units.', 'The length with the bigger number in the smaller unit.', 'Change both to mm before comparing: 2 cm is 20 mm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.MM_CM_RELATIONSHIP.M_HALF_CM_AS_50', 'MATH.G6.MEASUR.LENGTH.MM_CM_RELATIONSHIP', 'Writes half a centimetre as 50 mm, halving 100 instead of 10.', '{"question":"4 and a half cm in cm and mm","wrong_answer":"4 cm 50 mm","correct_answer":"4 cm 5 mm"}'::jsonb, 'Uses the 100 from metres and centimetres.', 'An answer with 50 mm.', 'Half of 10 mm is 5 mm: look at half a centimetre on the ruler.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.CONVERT_TO_MM.M_MM_PART_DROPPED', 'MATH.G6.MEASUR.LENGTH.CONVERT_TO_MM', 'Changes the cm to mm but forgets to add the mm.', '{"question":"4 cm 7 mm in mm","wrong_answer":"40 mm","correct_answer":"47 mm"}'::jsonb, 'Changes one part and stops.', 'The cm part changed alone as an option.', 'Write it as two parts: 4 cm = 40 mm, plus 7 mm, makes 47 mm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.CONVERT_TO_MM.M_DIVIDE_NOT_MULTIPLY', 'MATH.G6.MEASUR.LENGTH.CONVERT_TO_MM', 'Divides by 10 to change cm to mm.', '{"question":"60 cm in mm","wrong_answer":"6 mm","correct_answer":"600 mm"}'::jsonb, 'Not sure which way to go, so divides.', 'The answer one hundred times too small.', 'A smaller unit needs more of them: multiply by 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.ADD_CM_MM.M_MM_ADDED_TO_CM', 'MATH.G6.MEASUR.LENGTH.ADD_CM_MM', 'Adds a length given only in mm to the cm of the other length.', '{"question":"3 cm 8 mm + 16 mm","wrong_answer":"19 cm 8 mm","correct_answer":"5 cm 4 mm"}'::jsonb, 'Adds the numbers it sees without matching the units.', 'An answer with the mm added to the cm.', 'Write 16 mm as 1 cm 6 mm first, then add cm to cm and mm to mm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.SUBTRACT_CM_MM.M_RENAME_AS_100', 'MATH.G6.MEASUR.LENGTH.SUBTRACT_CM_MM', 'Renames 1 cm as 100 mm when there are too few mm.', '{"question":"5 cm 2 mm - 2 cm 7 mm","wrong_answer":"2 cm 95 mm (102 mm - 7 mm)","correct_answer":"2 cm 5 mm"}'::jsonb, 'Uses the 100 from metres and centimetres.', 'An answer with far too many mm.', '1 cm is 10 mm: 5 cm 2 mm becomes 4 cm 12 mm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.SUBTRACT_CM_MM.M_MM_COPIED_FROM_NOTHING', 'MATH.G6.MEASUR.LENGTH.SUBTRACT_CM_MM', 'Takes a cm and mm length from whole cm by subtracting the cm and copying the mm.', '{"question":"8 cm - 2 cm 5 mm","wrong_answer":"6 cm 5 mm","correct_answer":"5 cm 5 mm"}'::jsonb, 'Has no mm to take from, so writes the 5 mm down.', 'The answer with the mm copied.', 'Rename one cm: 8 cm = 7 cm 10 mm, then subtract.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.MULTIPLY_CM_MM.M_MULTIPLY_MM_ONLY', 'MATH.G6.MEASUR.LENGTH.MULTIPLY_CM_MM', 'Multiplies the mm and leaves the cm as they were.', '{"question":"2 cm 4 mm x 3","wrong_answer":"2 cm 12 mm (3 cm 2 mm)","correct_answer":"7 cm 2 mm"}'::jsonb, 'Multiplies one part only.', 'The answer with only the mm multiplied.', 'Each part is multiplied: 2 cm x 3 and 4 mm x 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.MULTIPLY_CM_MM.M_RENAMED_CM_NOT_ADDED', 'MATH.G6.MEASUR.LENGTH.MULTIPLY_CM_MM', 'Renames the mm product as cm and mm but does not add the new cm.', '{"question":"3 cm 6 mm x 4","wrong_answer":"12 cm 4 mm","correct_answer":"14 cm 4 mm"}'::jsonb, 'Writes the leftover mm and forgets where the cm go.', 'An answer two cm short.', 'Write the new cm above the cm column and add them in.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.DIVIDE_CM_MM.M_DIVIDE_CM_KEEP_MM', 'MATH.G6.MEASUR.LENGTH.DIVIDE_CM_MM', 'Divides the cm and keeps the mm unchanged.', '{"question":"8 cm 4 mm / 4","wrong_answer":"2 cm 4 mm","correct_answer":"2 cm 1 mm"}'::jsonb, 'Divides one part only.', 'The answer with the mm not divided.', 'Every part is shared: 8 cm / 4 and 4 mm / 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.DIVIDE_CM_MM.M_REMAINDER_WRITTEN_AS_MM', 'MATH.G6.MEASUR.LENGTH.DIVIDE_CM_MM', 'Writes the remainder of the cm as mm and ignores the mm in the question.', '{"question":"9 cm 6 mm / 4","wrong_answer":"2 cm 1 mm (9 / 4 = 2 remainder 1)","correct_answer":"2 cm 4 mm"}'::jsonb, 'Treats the remainder as the mm part of the answer.', 'An answer whose mm is the remainder.', 'Change to mm first: 96 mm / 4 = 24 mm = 2 cm 4 mm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_PRACTICAL.M_OVERLAP_INCLUDED', 'MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_PRACTICAL', 'Measures the whole string, overlap and all, as the circumference.', '{"question":"A string wrapped once round a tin overlaps by 2 cm and measures 27 cm in all. What is the circumference?","wrong_answer":"27 cm","correct_answer":"25 cm"}'::jsonb, 'Does not see that the overlap goes round twice.', 'The full string length as an option.', 'Mark where the string meets itself and measure only to that mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_PRACTICAL.M_TURNS_MULTIPLIED', 'MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_PRACTICAL', 'Multiplies the distance by the circumference to find the number of turns.', '{"question":"A wheel of circumference 2 m rolls 100 m. How many turns does it make?","wrong_answer":"200","correct_answer":"50"}'::jsonb, 'Multiplies whenever a wheel and turns appear.', 'The product as an option.', 'Each turn moves 2 m: how many 2 m are in 100 m?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_DIAMETER_RELATION.M_DIAMETER_BY_MULTIPLYING', 'MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_DIAMETER_RELATION', 'Multiplies the circumference by pi to find the diameter.', '{"question":"Circumference 44 cm, pi = 22/7. What is the diameter?","wrong_answer":"about 138 cm (44 x 22/7)","correct_answer":"14 cm"}'::jsonb, 'Uses the rule for circumference in the wrong direction.', 'A diameter bigger than the circumference.', 'The diameter is about a third of the circumference: divide by pi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_DIAMETER_RELATION.M_RATIO_GROWS_WITH_SIZE', 'MATH.G6.MEASUR.LENGTH.CIRCUMFERENCE_DIAMETER_RELATION', 'Believes the circumference is a bigger number of diameters for a bigger circle.', '{"question":"Circle A has diameter 7 cm and circle B 70 cm. Is circumference / diameter bigger for B?","wrong_answer":"Yes, B is bigger","correct_answer":"No: it is about 3.14 (22/7) for both"}'::jsonb, 'Thinks everything about a bigger circle is bigger.', 'A choice between the two circles.', 'Measure a bottle top and a bicycle wheel and divide: the answer is about 3 each time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_TRIANGLE.M_NO_HALF', 'MATH.G6.MEASUR.AREA.AREA_TRIANGLE', 'Multiplies the base by the height and does not halve.', '{"question":"Triangle base 8 cm, height 5 cm: area?","wrong_answer":"40 cm2","correct_answer":"20 cm2"}'::jsonb, 'Remembers the rectangle rule.', 'The rectangle area as an option.', 'Cut a rectangle along a diagonal and compare the two halves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_TRIANGLE.M_SLANT_SIDE_AS_HEIGHT', 'MATH.G6.MEASUR.AREA.AREA_TRIANGLE', 'Uses the slanting side instead of the perpendicular height.', '{"question":"Base 10 cm, perpendicular height 6 cm, slanting side 8 cm","wrong_answer":"40 cm2 (half of 10 x 8)","correct_answer":"30 cm2"}'::jsonb, 'Takes any side as the height.', 'Value computed from the slant.', 'Draw the height at a right angle to the base.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_TRIANGLE.M_PERIMETER_FOR_AREA', 'MATH.G6.MEASUR.AREA.AREA_TRIANGLE', 'Adds the sides, giving the perimeter in place of the area.', '{"question":"A triangle has sides 5 cm, 5 cm and 6 cm. Its base is 6 cm and its height is 4 cm. Area?","wrong_answer":"16 cm2 (the sides added: the perimeter)","correct_answer":"12 cm2"}'::jsonb, 'Confuses area and perimeter.', 'Perimeter as a distractor.', 'Colour the inside for area, trace the edge for perimeter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_COMBINED.M_ONE_PART_ONLY', 'MATH.G6.MEASUR.AREA.AREA_COMBINED', 'Finds the area of only one of the parts.', '{"question":"L-shape made of two rectangles","wrong_answer":"one rectangle area","correct_answer":"total of both"}'::jsonb, 'Does not break the shape into all its parts.', 'Area of the larger part only.', 'Draw the dividing line and label each part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_COMBINED.M_CUT_OUT_ADDED', 'MATH.G6.MEASUR.AREA.AREA_COMBINED', 'Adds the area of a cut-out part instead of subtracting it.', '{"question":"Rectangle 10 by 6 with a 2 by 2 square cut out","wrong_answer":"64 cm2","correct_answer":"56 cm2"}'::jsonb, 'Adds all the numbers it can see.', 'The sum of areas as a distractor.', 'Draw the missing part with a dotted line and say it is not there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_CIRCLE_BY_COUNTING.M_COUNT_WHOLE_ONLY', 'MATH.G6.MEASUR.AREA.AREA_CIRCLE_BY_COUNTING', 'Counts only the whole squares and ignores the part squares.', '{"question":"A circle covers 20 whole squares and 12 part squares","wrong_answer":"20 cm2","correct_answer":"26 cm2"}'::jsonb, 'Thinks part squares do not count.', 'Whole-square count only.', 'Count part squares in pairs as one whole square.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_CIRCLE_BY_COUNTING.M_COUNT_PART_AS_WHOLE', 'MATH.G6.MEASUR.AREA.AREA_CIRCLE_BY_COUNTING', 'Counts every part square as a whole square.', '{"question":"20 whole squares, 12 part squares","wrong_answer":"32 cm2","correct_answer":"26 cm2"}'::jsonb, 'Does not see a part square as less than a whole.', 'All squares counted whole.', 'Halve the number of part squares before adding.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_TRIANGLE.M_HALF_BOTH', 'MATH.G6.MEASUR.AREA.AREA_TRIANGLE', 'Halves both the base and the height before multiplying.', '{"question":"Triangle base 8 cm, height 5 cm: area?","wrong_answer":"10 cm2 (4 x 2.5)","correct_answer":"20 cm2"}'::jsonb, 'Knows "half" is in the rule and applies it to every length.', 'A quarter of base times height as an option.', 'Cut a rectangle 8 by 5 along its diagonal: each triangle is half of 40.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_TRIANGLE.M_AREA_IN_CM', 'MATH.G6.MEASUR.AREA.AREA_TRIANGLE', 'Gives an area in cm instead of cm2.', '{"question":"Triangle base 8 cm, height 5 cm: area?","wrong_answer":"20 cm","correct_answer":"20 cm2"}'::jsonb, 'Copies the unit of the lengths.', 'The right number with the wrong unit.', 'Area counts squares: each square is 1 cm by 1 cm, written cm2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_COMBINED.M_OVERLAP_COUNTED_TWICE', 'MATH.G6.MEASUR.AREA.AREA_COMBINED', 'Uses a length of the whole shape for one of its parts, so a piece is counted twice.', '{"question":"An L-shape is a 10 cm by 4 cm rectangle on top of a 4 cm by 6 cm rectangle (total height 10 cm). Area?","wrong_answer":"80 cm2 (10 x 4 + 4 x 10)","correct_answer":"64 cm2 (10 x 4 + 4 x 6)"}'::jsonb, 'Reads the 10 cm side for the second rectangle as well.', 'The area with the corner counted twice.', 'Draw the split line and write the two lengths of each part on the part before multiplying.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_COMBINED.M_TRIANGLE_PART_NOT_HALVED', 'MATH.G6.MEASUR.AREA.AREA_COMBINED', 'Forgets to halve the triangle part of a combined shape.', '{"question":"A house shape: a 6 cm square with a triangle roof of base 6 cm and height 4 cm. Area?","wrong_answer":"60 cm2 (36 + 24)","correct_answer":"48 cm2 (36 + 12)"}'::jsonb, 'Works the triangle as a rectangle while busy with the other parts.', 'The answer with the triangle not halved.', 'Name each part first: square, triangle. The triangle uses half base times height.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_CIRCLE_BY_COUNTING.M_SQUARE_AROUND_CIRCLE', 'MATH.G6.MEASUR.AREA.AREA_CIRCLE_BY_COUNTING', 'Counts every square inside the square drawn round the circle.', '{"question":"A circle of diameter 6 cm is drawn on 1 cm squares. Estimate its area.","wrong_answer":"36 cm2 (the 6 by 6 square)","correct_answer":"about 28 cm2"}'::jsonb, 'Takes the box the circle sits in as the circle.', 'The area of the surrounding square as an option.', 'Shade only the squares inside the circle; the corners of the box are outside it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.AREA.AREA_CIRCLE_BY_COUNTING.M_ESTIMATE_CALLED_EXACT', 'MATH.G6.MEASUR.AREA.AREA_CIRCLE_BY_COUNTING', 'Believes counting squares gives the exact area.', '{"question":"A circle covers 20 whole squares and 12 part squares, so about 26 cm2. Is this exact?","wrong_answer":"Yes, it was counted","correct_answer":"No: the part squares were each taken as a half, so it is an estimate"}'::jsonb, 'Thinks counting is always exact.', 'A yes-or-no choice about the estimate.', 'Look at the part squares: some are nearly whole, some are tiny, so taking each as a half is only close.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.CAPACITY.CM3_ML_LITRE_RELATION.M_CM3_HUNDRED_ML', 'MATH.G6.MEASUR.CAPACITY.CM3_ML_LITRE_RELATION', 'Believes 1 cm3 is 100 ml or that 1 litre is 100 cm3.', '{"question":"A box of 1,000 cm3 holds how many litres?","wrong_answer":"10 litres","correct_answer":"1 litre"}'::jsonb, 'Takes 100 as the usual relationship between units.', 'Option ten times too large.', 'Fill a 1 cm cube with water and note the very small amount.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.CAPACITY.CM3_ML_LITRE_RELATION.M_CM3_NOT_CAPACITY', 'MATH.G6.MEASUR.CAPACITY.CM3_ML_LITRE_RELATION', 'Believes cm3 measures length or area, not capacity.', '{"question":"Which unit measures how much a box holds?","wrong_answer":"cm","correct_answer":"cm3"}'::jsonb, 'Does not link the cube with space inside.', 'Linear or area unit as option.', 'Build a 3 by 3 by 3 block of cubes and count the cubes inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.CAPACITY.LITRES_TO_ML.M_TIMES_HUNDRED', 'MATH.G6.MEASUR.CAPACITY.LITRES_TO_ML', 'Multiplies litres by 100 to get millilitres.', '{"question":"3 l in ml","wrong_answer":"300 ml","correct_answer":"3,000 ml"}'::jsonb, 'Mixes with centimetres and metres.', 'Ten times too small.', 'Fill a 1 litre bottle using a 100 ml cup and count the cups.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.CAPACITY.LITRES_TO_ML.M_DECIMAL_LITRE', 'MATH.G6.MEASUR.CAPACITY.LITRES_TO_ML', 'Reads 2.5 litres as 2 l 5 ml.', '{"question":"2.5 l in ml","wrong_answer":"2,005 ml","correct_answer":"2,500 ml"}'::jsonb, 'Reads the decimal as a count of ml.', 'Option with the 5 as ml.', 'Think of 0.5 l as half of 1,000 ml.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.CAPACITY.ML_TO_LITRES.M_DIVIDE_BY_HUNDRED', 'MATH.G6.MEASUR.CAPACITY.ML_TO_LITRES', 'Divides by 100 instead of 1,000.', '{"question":"4,500 ml in litres","wrong_answer":"45 l","correct_answer":"4.5 l"}'::jsonb, 'Mixes the units.', 'Ten times too large.', 'Count thousands in 4,500.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.CAPACITY.ML_TO_LITRES.M_LEFTOVER_ML_LOST', 'MATH.G6.MEASUR.CAPACITY.ML_TO_LITRES', 'Gives only the whole litres and drops the leftover ml.', '{"question":"3,250 ml in litres and millilitres","wrong_answer":"3 l","correct_answer":"3 l 250 ml"}'::jsonb, 'Divides and ignores the remainder.', 'Whole litres only.', 'Write the quotient and the remainder with their units.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.CAPACITY.CM3_ML_LITRE_RELATION.M_CM3_AS_LITRES', 'MATH.G6.MEASUR.CAPACITY.CM3_ML_LITRE_RELATION', 'Gives the number of cm3 as the number of litres.', '{"question":"A box of 5,000 cm3 holds how many litres?","wrong_answer":"5,000","correct_answer":"5"}'::jsonb, 'Does not change cm3 to litres at all.', 'The cm3 value as an option.', 'Say how many cm3 fill one litre, then divide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.CAPACITY.CM3_ML_LITRE_RELATION.M_CUBE_SIDE_AS_ML', 'MATH.G6.MEASUR.CAPACITY.CM3_ML_LITRE_RELATION', 'Uses the length of a side, or three sides added, as the capacity of a cube.', '{"question":"A cube with 10 cm sides holds how many ml?","wrong_answer":"30 ml (10 + 10 + 10)","correct_answer":"1,000 ml"}'::jsonb, 'Adds or copies the lengths instead of finding the volume.', 'The sum of the sides as an option.', 'Volume is length x width x height: 10 x 10 x 10 = 1,000 cm3, and 1 cm3 holds 1 ml.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.CAPACITY.LITRES_TO_ML.M_LITRES_ML_JOINED', 'MATH.G6.MEASUR.CAPACITY.LITRES_TO_ML', 'Writes the litres and the millilitres side by side, losing the place-holder zero.', '{"question":"3 l 25 ml in ml","wrong_answer":"325 ml","correct_answer":"3,025 ml"}'::jsonb, 'Joins the digits as they are said.', 'The joined digits as an option.', 'Change the litres first: 3 l = 3,000 ml, then add 25 ml.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.CAPACITY.LITRES_TO_ML.M_DIVIDE_FOR_SMALLER_UNIT', 'MATH.G6.MEASUR.CAPACITY.LITRES_TO_ML', 'Divides by 1,000 to change litres to ml.', '{"question":"4 l in ml","wrong_answer":"0.004 ml","correct_answer":"4,000 ml"}'::jsonb, 'Not sure which way to go, so divides.', 'A tiny answer as an option.', 'A smaller unit needs more of them: multiply by 1,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.CAPACITY.ML_TO_LITRES.M_ML_PLACE_HOLDER_LOST', 'MATH.G6.MEASUR.CAPACITY.ML_TO_LITRES', 'Loses the zero in the ml part when writing litres and ml or a decimal.', '{"question":"2,050 ml in litres and millilitres","wrong_answer":"2 l 5 ml (or 2.5 l)","correct_answer":"2 l 50 ml (2.05 l)"}'::jsonb, 'Drops the zero between the litres and the ml.', 'The answer with the zero dropped.', 'Split off three digits from the right for the ml: 2 | 050.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.CAPACITY.ML_TO_LITRES.M_MULTIPLY_FOR_BIGGER_UNIT', 'MATH.G6.MEASUR.CAPACITY.ML_TO_LITRES', 'Multiplies by 1,000 to change ml to litres.', '{"question":"3,000 ml in litres","wrong_answer":"3,000,000 l","correct_answer":"3 l"}'::jsonb, 'Multiplies whenever 1,000 appears.', 'A huge answer as an option.', 'A bigger unit needs fewer of them: divide by 1,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.TONNE_AS_UNIT.M_TONNE_LESS_THAN_KG', 'MATH.G6.MEASUR.MASS.TONNE_AS_UNIT', 'Believes the tonne is a small unit, or smaller than a kilogramme.', '{"question":"Which is heavier, 1 t or 100 kg?","wrong_answer":"100 kg","correct_answer":"1 t"}'::jsonb, 'Confuses the tonne with the gramme because of the sound of the words.', 'Which-is-heavier item.', 'Compare 1,000 sacks of 1 kg against one lorry load.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.TONNE_AS_UNIT.M_UNIT_FOR_SMALL_OBJECT', 'MATH.G6.MEASUR.MASS.TONNE_AS_UNIT', 'Chooses tonnes for a small object such as a goat or a bag of sugar.', '{"question":"Unit for the mass of a goat?","wrong_answer":"t","correct_answer":"kg"}'::jsonb, 'Wants the biggest unit for a big animal.', 'Familiar animals with tonnes as an option.', 'Compare the mass with the mass of a lorry.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.ITEMS_IN_TONNES.M_BIG_MEANS_TONNES', 'MATH.G6.MEASUR.MASS.ITEMS_IN_TONNES', 'Picks anything that looks big as measured in tonnes, such as a cow or a bus passenger.', '{"question":"Which is measured in tonnes?","wrong_answer":"a cow","correct_answer":"a load of sand on a lorry"}'::jsonb, 'Judges by size, not by the number of kg.', 'Large animals as distractors.', 'Ask if the mass is more than 1,000 kg.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.KG_TONNE_RELATIONSHIP.M_HUNDRED_KG', 'MATH.G6.MEASUR.MASS.KG_TONNE_RELATIONSHIP', 'Believes 1 tonne is 100 kg.', '{"question":"How many 50 kg sacks make a tonne?","wrong_answer":"2 sacks","correct_answer":"20 sacks"}'::jsonb, 'Takes 100 as the standard multiplier.', 'Answer for 100 kg.', 'Count 20 sacks of 50 kg on a number line to 1,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.KG_TONNE_RELATIONSHIP.M_TENS_NOT_THOUSANDS', 'MATH.G6.MEASUR.MASS.KG_TONNE_RELATIONSHIP', 'Believes 1 tonne is 10 kg.', '{"question":"How many kg in 2 tonnes?","wrong_answer":"20 kg","correct_answer":"2,000 kg"}'::jsonb, 'Mixes up the number of zeros.', 'Answer ten times too small.', 'Use 1 tonne = 1,000 kg.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.ESTIMATE_TONNES.M_UNIT_NOT_CONVERTED', 'MATH.G6.MEASUR.MASS.ESTIMATE_TONNES', 'Estimates using the kilogram count but gives it as tonnes without dividing.', '{"question":"40 bags of 50 kg: estimate in tonnes","wrong_answer":"2,000 t","correct_answer":"2 t"}'::jsonb, 'Does not change kg to tonnes.', 'Large number in tonnes.', 'Add the kg first, then divide by 1,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
