INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.CONVERT_KG_TONNES.M_DIVIDE_BY_HUNDRED_TONNES', 'MATH.G6.MEASUR.MASS.CONVERT_KG_TONNES', 'Divides kg by 100 to get tonnes.', '{"question":"4,500 kg in tonnes","wrong_answer":"45 t","correct_answer":"4.5 t"}'::jsonb, 'Uses 100 for the relationship.', 'Ten times too large.', 'Divide by 1,000: 4,500 kg is 4 t 500 kg.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.CONVERT_KG_TONNES.M_TONNES_AS_KG_TEN', 'MATH.G6.MEASUR.MASS.CONVERT_KG_TONNES', 'Multiplies tonnes by 10 to get kg.', '{"question":"3.5 t in kg","wrong_answer":"35 kg","correct_answer":"3,500 kg"}'::jsonb, 'Confuses tens and thousands.', 'Ten times, not 1,000.', 'Use the 1,000 kg lorry-load picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.ADD_TONNES_KG.M_KG_OVER_THOUSAND_LEFT', 'MATH.G6.MEASUR.MASS.ADD_TONNES_KG', 'Leaves 1,000 kg or more in the kg column.', '{"question":"2 t 300 kg + 3 t 900 kg","wrong_answer":"5 t 1,200 kg","correct_answer":"6 t 200 kg"}'::jsonb, 'Does not rename 1,000 kg as 1 t.', 'Answer with kg over 999.', 'After adding, rename every 1,000 kg as 1 t.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.ADD_TONNES_KG.M_ADD_AS_DECIMAL_TONNES', 'MATH.G6.MEASUR.MASS.ADD_TONNES_KG', 'Adds as decimals (2.300 + 3.900) but reads 0.2 as 200 kg wrongly, or ignores the zero in 2 t 050 kg.', '{"question":"1 t 50 kg + 2 t 450 kg","wrong_answer":"3 t 5 kg (the place-holder zero of 50 lost)","correct_answer":"3 t 500 kg"}'::jsonb, 'Loses a place holder zero.', 'Total with a lost zero.', 'Write each kg part with three digits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.SUBTRACT_TONNES_KG.M_SMALLER_FROM_LARGER_KG', 'MATH.G6.MEASUR.MASS.SUBTRACT_TONNES_KG', 'Subtracts the smaller kg from the larger whatever the order.', '{"question":"5 t 200 kg - 2 t 700 kg","wrong_answer":"3 t 500 kg","correct_answer":"2 t 500 kg"}'::jsonb, 'Avoids renaming.', 'Reverse-subtraction kg part.', 'Rename 1 t as 1,000 kg.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.SUBTRACT_TONNES_KG.M_TONNE_NOT_REDUCED', 'MATH.G6.MEASUR.MASS.SUBTRACT_TONNES_KG', 'Adds 1,000 kg but does not take 1 t off.', '{"question":"6 t 300 kg - 2 t 800 kg","wrong_answer":"4 t 500 kg","correct_answer":"3 t 500 kg"}'::jsonb, 'Forgets the second half of renaming.', 'Answer 1 t too large.', 'Write "6 becomes 5" above the tonnes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.MULTIPLY_TONNES_KG.M_KG_NOT_RENAMED_AFTER_MULT', 'MATH.G6.MEASUR.MASS.MULTIPLY_TONNES_KG', 'Leaves the product of the kg above 999 in the kg column.', '{"question":"2 t 600 kg x 4","wrong_answer":"8 t 2,400 kg","correct_answer":"10 t 400 kg"}'::jsonb, 'Does not rename after multiplying.', 'Answer with kg over 999.', 'Rename every 1,000 kg as 1 t after multiplying.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.MULTIPLY_TONNES_KG.M_MULTIPLY_TONNES_ONLY', 'MATH.G6.MEASUR.MASS.MULTIPLY_TONNES_KG', 'Multiplies the tonnes and leaves the kg unchanged.', '{"question":"1 t 250 kg x 3","wrong_answer":"3 t 250 kg","correct_answer":"3 t 750 kg"}'::jsonb, 'Treats the kg as a label.', 'Answer with kg not multiplied.', 'Multiply both parts, then rename.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.DIVIDE_TONNES_KG.M_REMAINDER_TONNE_LOST', 'MATH.G6.MEASUR.MASS.DIVIDE_TONNES_KG', 'Divides the tonnes and the kg separately and loses the leftover tonne.', '{"question":"5 t 400 kg / 4","wrong_answer":"1 t 100 kg","correct_answer":"1 t 350 kg"}'::jsonb, 'Does not convert the leftover tonne to kg.', 'Answer from dividing parts separately.', 'Change the whole mass to kg and divide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.DIVIDE_TONNES_KG.M_DIVIDE_THE_WRONG_WAY_ROUND', 'MATH.G6.MEASUR.MASS.DIVIDE_TONNES_KG', 'Divides the number of parts by the mass.', '{"question":"9 t shared equally among 3 trucks","wrong_answer":"0.33 t","correct_answer":"3 t"}'::jsonb, 'Reverses dividend and divisor.', 'Fraction-like answer.', 'Ask whether each part can be larger than the whole.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.TONNE_AS_UNIT.M_UNIT_TOO_SMALL', 'MATH.G6.MEASUR.MASS.TONNE_AS_UNIT', 'Chooses the gramme for something heavy.', '{"question":"Unit for the mass of a goat?","wrong_answer":"g","correct_answer":"kg"}'::jsonb, 'Picks the first unit that comes to mind.', 'The gramme as a distractor.', 'Hold a one-kilogramme packet of sugar and compare it with the object.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.ITEMS_IN_TONNES.M_LOAD_TOO_LIGHT', 'MATH.G6.MEASUR.MASS.ITEMS_IN_TONNES', 'Gives a lorry load in kg or g, as if it were light.', '{"question":"A lorry of sand has a mass of about?","wrong_answer":"9 kg","correct_answer":"9 t"}'::jsonb, 'Does not see how heavy a lorry load is.', 'Small unit for a big load.', 'Compare with a bag of 50 kg: how many bags is a lorry?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.DIVIDE_TONNES_KG.M_UNIT_NOT_CHANGED_BACK_T', 'MATH.G6.MEASUR.MASS.DIVIDE_TONNES_KG', 'Divides in kg correctly but gives the answer in tonnes, or the reverse.', '{"question":"3 t 600 kg shared by 4: each in kg?","wrong_answer":"0.9 (t)","correct_answer":"900 kg"}'::jsonb, 'Does not look at the unit the question asks for.', 'Answer ten or a thousand times too small.', 'Underline the unit in the question before writing the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.TONNE_AS_UNIT.M_CAPACITY_UNIT_FOR_MASS', 'MATH.G6.MEASUR.MASS.TONNE_AS_UNIT', 'Chooses a unit of capacity (litres) for the mass of a heavy load.', '{"question":"Which unit is best for the mass of a lorry load of maize?","wrong_answer":"litres","correct_answer":"tonnes"}'::jsonb, 'Mixes up "how much it holds" with "how heavy it is".', 'A capacity unit among the choices.', 'Mass answers "how heavy?": g, kg or t. Litres answer "how much does it hold?".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.ITEMS_IN_TONNES.M_SMALL_PIECES_NEVER_TONNES', 'MATH.G6.MEASUR.MASS.ITEMS_IN_TONNES', 'Believes a load of small, light things cannot be measured in tonnes.', '{"question":"Which is measured in tonnes: a tomato, a crate of tomatoes or a lorry load of tomatoes?","wrong_answer":"none: tomatoes are light","correct_answer":"a lorry load of tomatoes"}'::jsonb, 'Judges by one piece, not by the whole load.', 'The answer "none" among the choices.', 'Ask how many crates fill a lorry: many light things together can be very heavy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.ITEMS_IN_TONNES.M_LIQUID_HAS_NO_MASS', 'MATH.G6.MEASUR.MASS.ITEMS_IN_TONNES', 'Believes a liquid load is measured only in litres and cannot have a mass in tonnes.', '{"question":"Can a tanker carrying 10,000 l of milk be weighed in tonnes?","wrong_answer":"No, milk is measured in litres","correct_answer":"Yes: about 10 t (1 l of milk is about 1 kg)"}'::jsonb, 'Has met liquids only with capacity units.', 'A no among the choices.', 'A full jerrycan is heavy to carry: liquids have mass too. 1 litre of water is about 1 kg.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.KG_TONNE_RELATIONSHIP.M_SACKS_MULTIPLIED', 'MATH.G6.MEASUR.MASS.KG_TONNE_RELATIONSHIP', 'Multiplies instead of dividing to find how many sacks make a tonne.', '{"question":"How many 50 kg sacks make a tonne?","wrong_answer":"50,000","correct_answer":"20"}'::jsonb, 'Sees 1,000 and 50 and multiplies.', 'The product as an option.', 'How many 50s are in 1,000? Count in fifties or divide 1,000 by 50.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.KG_TONNE_RELATIONSHIP.M_PART_TONNE_FROM_100', 'MATH.G6.MEASUR.MASS.KG_TONNE_RELATIONSHIP', 'Works out a part of a tonne from 100 kg.', '{"question":"How many kg is a quarter of a tonne?","wrong_answer":"25 kg","correct_answer":"250 kg"}'::jsonb, 'Thinks of a tonne as 100 kg, as a metre is 100 cm.', 'An answer ten times too small as an option.', 'A tonne is 1,000 kg: a quarter of 1,000 is 250.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.ESTIMATE_TONNES.M_ESTIMATE_TEN_TIMES_OFF', 'MATH.G6.MEASUR.MASS.ESTIMATE_TONNES', 'Gives an estimate ten times too big or too small.', '{"question":"A lorry carries 200 bags of 50 kg. About how many tonnes?","wrong_answer":"100 t","correct_answer":"10 t"}'::jsonb, 'Loses or adds a zero when changing kg to t.', 'An estimate ten times off as an option.', 'Twenty 50 kg bags make a tonne; how many twenties are in 200?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.ESTIMATE_TONNES.M_ONE_ITEM_FOR_LOAD', 'MATH.G6.MEASUR.MASS.ESTIMATE_TONNES', 'Gives the mass of one item as the estimate for the whole load.', '{"question":"A lorry carries 200 bags of 50 kg. About how heavy is the load?","wrong_answer":"about 50 kg","correct_answer":"about 10 t"}'::jsonb, 'Reads the mass of one bag off the story.', 'The mass of one item as an option.', 'Ask: is the lorry as heavy as one bag, or as all the bags together?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.CONVERT_KG_TONNES.M_KG_PLACE_HOLDER_LOST', 'MATH.G6.MEASUR.MASS.CONVERT_KG_TONNES', 'Joins the tonnes and kilogrammes without the zero, so the kg part is in the wrong places.', '{"question":"2 t 45 kg in kg","wrong_answer":"2,450 kg","correct_answer":"2,045 kg"}'::jsonb, 'Writes the digits as they are said.', 'The joined digits as an option.', 'The kg part always takes three places: 2 t 045 kg = 2,045 kg.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.CONVERT_KG_TONNES.M_KG_TO_T_MULTIPLY', 'MATH.G6.MEASUR.MASS.CONVERT_KG_TONNES', 'Multiplies by 1,000 to change kg to tonnes.', '{"question":"3,000 kg in tonnes","wrong_answer":"3,000,000 t","correct_answer":"3 t"}'::jsonb, 'Multiplies whenever 1,000 appears.', 'A huge answer as an option.', 'A bigger unit needs fewer of them: divide by 1,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.ADD_TONNES_KG.M_RENAMED_TONNE_NOT_ADDED', 'MATH.G6.MEASUR.MASS.ADD_TONNES_KG', 'Renames 1,000 kg as a tonne but does not add that tonne.', '{"question":"2 t 300 kg + 3 t 900 kg","wrong_answer":"5 t 200 kg","correct_answer":"6 t 200 kg"}'::jsonb, 'Takes 1,000 off the kg and forgets where it goes.', 'An answer one tonne short.', 'Write the new tonne above the tonne column and add it in.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.ADD_TONNES_KG.M_NUMBERS_ADDED_UNITS_IGNORED', 'MATH.G6.MEASUR.MASS.ADD_TONNES_KG', 'Adds the numbers of a tonnes amount and a kg amount as if they were the same unit.', '{"question":"3 t + 450 kg","wrong_answer":"453 kg","correct_answer":"3 t 450 kg (3,450 kg)"}'::jsonb, 'Adds the numbers it sees.', 'The plain sum of the numbers as an option.', 'Change both to kg first: 3,000 kg + 450 kg.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.SUBTRACT_TONNES_KG.M_TONNE_AS_100_KG', 'MATH.G6.MEASUR.MASS.SUBTRACT_TONNES_KG', 'Renames 1 tonne as 100 kg when there are too few kg.', '{"question":"6 t 50 kg - 2 t 80 kg","wrong_answer":"3 t 70 kg (5 t 150 kg - 2 t 80 kg)","correct_answer":"3 t 970 kg"}'::jsonb, 'Uses 100 for the rename, as with metres and centimetres.', 'An answer from renaming with 100.', '1 t is 1,000 kg: 6 t 50 kg becomes 5 t 1,050 kg.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.SUBTRACT_TONNES_KG.M_KG_COPIED_FROM_NOTHING', 'MATH.G6.MEASUR.MASS.SUBTRACT_TONNES_KG', 'Takes kg from whole tonnes by taking a tonne off and copying the kg.', '{"question":"4 t - 350 kg","wrong_answer":"3 t 350 kg","correct_answer":"3 t 650 kg"}'::jsonb, 'Has no kg to take from, so writes the 350 down.', 'The answer with the kg copied.', 'Rename one tonne: 4 t = 3 t 1,000 kg; 1,000 - 350 = 650.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.MULTIPLY_TONNES_KG.M_RENAMED_T_NOT_ADDED_MULT', 'MATH.G6.MEASUR.MASS.MULTIPLY_TONNES_KG', 'Renames the kg product but drops the tonnes it makes.', '{"question":"2 t 600 kg x 4","wrong_answer":"8 t 400 kg","correct_answer":"10 t 400 kg"}'::jsonb, 'Writes the leftover kg and forgets the new tonnes.', 'An answer two tonnes short.', 'Write the new tonnes above the tonne column and add them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.MULTIPLY_TONNES_KG.M_KG_RENAMED_BY_100', 'MATH.G6.MEASUR.MASS.MULTIPLY_TONNES_KG', 'Renames kg as tonnes by dividing by 100.', '{"question":"2 t 600 kg x 4","wrong_answer":"32 t (2,400 kg taken as 24 t)","correct_answer":"10 t 400 kg"}'::jsonb, 'Uses 100 instead of 1,000.', 'A far too heavy answer as an option.', '1,000 kg make a tonne: 2,400 kg is 2 t 400 kg.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MASS.DIVIDE_TONNES_KG.M_SHARE_KG_ONLY', 'MATH.G6.MEASUR.MASS.DIVIDE_TONNES_KG', 'Divides the kg and keeps the tonnes as they were.', '{"question":"8 t 400 kg shared equally by 4 lorries","wrong_answer":"8 t 100 kg","correct_answer":"2 t 100 kg"}'::jsonb, 'Divides one part only.', 'The answer with the tonnes not divided.', 'Every part is shared: 8 t / 4 and 400 kg / 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.AM_PM_IDENTIFY.M_NOON_IS_AM', 'MATH.G6.MEASUR.TIME.AM_PM_IDENTIFY', 'Believes the hours just before and after noon are both a.m.', '{"question":"Is 12:30 a.m. or p.m.?","wrong_answer":"a.m.","correct_answer":"p.m."}'::jsonb, 'Thinks p.m. starts at 1.', 'Times around 12.', 'Put noon on a day line: a.m. before, p.m. after.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.AM_PM_IDENTIFY.M_NIGHT_IS_PM', 'MATH.G6.MEASUR.TIME.AM_PM_IDENTIFY', 'Puts early morning hours after midnight (such as 2 a.m.) in the p.m.', '{"question":"A night watchman starts at 2 o''clock in the night","wrong_answer":"p.m.","correct_answer":"a.m."}'::jsonb, 'Treats night as p.m.', 'Night-time events.', 'Day line: midnight to noon is a.m.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.WRITE_AM_PM.M_TWELVE_AT_NIGHT', 'MATH.G6.MEASUR.TIME.WRITE_AM_PM', 'Writes 12 midnight as 12 noon or gets 12:15 at night as p.m.', '{"question":"12:15 at night","wrong_answer":"12:15 p.m.","correct_answer":"12:15 a.m."}'::jsonb, 'Confuses the two 12 o''clocks.', 'Times just past 12.', 'Draw the day line with both 12s marked.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.WRITE_AM_PM.M_AM_PM_LEFT_OUT', 'MATH.G6.MEASUR.TIME.WRITE_AM_PM', 'Writes a time without a.m. or p.m. when the question needs it.', '{"question":"Time school ends, 4 o''clock in the afternoon","wrong_answer":"4:00","correct_answer":"4:00 p.m."}'::jsonb, 'Treats the number as enough.', 'Time written without a.m. or p.m.', 'Say the part of the day before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.AM_PM_TO_24H_RELATE.M_ADD_TEN', 'MATH.G6.MEASUR.TIME.AM_PM_TO_24H_RELATE', 'Adds 10 or 100 to turn p.m. into 24-hour time.', '{"question":"Which 24-hour time is 3 p.m.?","wrong_answer":"13:00","correct_answer":"15:00"}'::jsonb, 'Does not know to add 12.', 'Wrong offsets as options.', 'Count on 12 hours from 3 on a 24-hour clock face.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.AM_PM_TO_24H_RELATE.M_SAME_NUMBER', 'MATH.G6.MEASUR.TIME.AM_PM_TO_24H_RELATE', 'Believes the 24-hour time is the same as the 12-hour time for p.m. hours.', '{"question":"5 p.m. is which 24-hour time?","wrong_answer":"05:00","correct_answer":"17:00"}'::jsonb, 'Does not see that 05:00 is morning.', 'The a.m. time as an option.', 'Match a clock face with 5 in the morning and 5 in the evening.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.CONVERT_12_24.M_ADD_12_TO_NOON', 'MATH.G6.MEASUR.TIME.CONVERT_12_24', 'Adds 12 to noon to give 24:00.', '{"question":"12 noon in 24-hour time","wrong_answer":"24:00","correct_answer":"12:00"}'::jsonb, 'Applies the add-12 rule to every p.m. time.', 'Noon and midnight times.', 'Noon is 12:00; add 12 only after noon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.CONVERT_12_24.M_MIDNIGHT_AS_12', 'MATH.G6.MEASUR.TIME.CONVERT_12_24', 'Writes midnight as 12:00 or 24:00 instead of 00:00.', '{"question":"12 midnight in 24-hour time as the start of a day","wrong_answer":"12:00","correct_answer":"00:00"}'::jsonb, 'Mixes noon and midnight.', 'Start-of-day times.', 'The 24-hour day begins at 00:00.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.TRAVEL_TIMETABLE.M_SUBTRACT_AS_DECIMAL', 'MATH.G6.MEASUR.TIME.TRAVEL_TIMETABLE', 'Subtracts times as decimals (10:45 from 12:15 as 1.70).', '{"question":"Leaves 10:45, arrives 12:15: journey time?","wrong_answer":"1 h 70 min or 1.70","correct_answer":"1 h 30 min"}'::jsonb, 'Treats minutes as hundredths.', 'Time subtracted as a decimal.', 'Count on from 10:45 to 11:00, then to 12:00, then to 12:15.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.TRAVEL_TIMETABLE.M_WRONG_ROW_READ', 'MATH.G6.MEASUR.TIME.TRAVEL_TIMETABLE', 'Reads the arrival time from the wrong row or column of the timetable.', '{"question":"Departure and arrival columns for two buses","wrong_answer":"the other bus''s arrival","correct_answer":"arrival from the same row"}'::jsonb, 'Loses place in a table.', 'Answers from a neighbouring row.', 'Ruler or finger across the row before reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.WRITE_AM_PM.M_QUARTER_TO_WRONG_HOUR', 'MATH.G6.MEASUR.TIME.WRITE_AM_PM', 'Writes quarter to six as 6:45 (quarter to is 15 minutes before the hour).', '{"question":"Quarter to 6 in the evening","wrong_answer":"6:45 p.m.","correct_answer":"5:45 p.m."}'::jsonb, 'Reads "quarter" as 45 minutes past.', 'Time with the hour not reduced.', 'On a clock, quarter to means the minute hand on 9: the hour hand has not reached the next hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.WRITE_AM_PM.M_EVENING_WITH_AM', 'MATH.G6.MEASUR.TIME.WRITE_AM_PM', 'Writes an evening or afternoon time with a.m.', '{"question":"Supper at half past 7 in the evening","wrong_answer":"7:30 a.m.","correct_answer":"7:30 p.m."}'::jsonb, 'Writes the time without thinking which half of the day.', 'The a.m. version of the time.', 'Ask whether it is before or after noon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.AM_PM_IDENTIFY.M_PM_STARTS_IN_EVENING', 'MATH.G6.MEASUR.TIME.AM_PM_IDENTIFY', 'Believes p.m. starts in the evening, so calls afternoon times a.m.', '{"question":"Is 3 o''clock in the afternoon a.m. or p.m.?","wrong_answer":"a.m.","correct_answer":"p.m."}'::jsonb, 'Links p.m. with darkness and evening, not with "after noon".', 'a.m. for an afternoon time.', 'Draw the day line: everything after 12 noon is p.m., even in daylight.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.AM_PM_IDENTIFY.M_SWAHILI_HOURS', 'MATH.G6.MEASUR.TIME.AM_PM_IDENTIFY', 'Reads a time said in Swahili time as the same hour in English time.', '{"question":"\"Saa tatu asubuhi\" in English time","wrong_answer":"3:00 a.m.","correct_answer":"9:00 a.m."}'::jsonb, 'Swahili time counts the hours from 6 a.m. (saa moja is 7 a.m.); the child uses the number without adding 6.', 'The hour six hours early as an option.', 'Swahili time starts at sunrise: add 6 hours to the Swahili hour (saa tatu = 3 + 6 = 9 o''clock).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.AM_PM_TO_24H_RELATE.M_AM_ALSO_PLUS_12', 'MATH.G6.MEASUR.TIME.AM_PM_TO_24H_RELATE', 'Adds 12 to a.m. times as well as p.m. times.', '{"question":"9 a.m. in 24-hour time","wrong_answer":"21:00","correct_answer":"09:00"}'::jsonb, 'Thinks the 24-hour clock always means adding 12.', 'An a.m. time with 12 added.', 'Only hours after noon get 12 added; morning hours stay the same.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.AM_PM_TO_24H_RELATE.M_MINUTES_CHANGED_TOO', 'MATH.G6.MEASUR.TIME.AM_PM_TO_24H_RELATE', 'Adds 12 to the minutes as well as the hours.', '{"question":"3:20 p.m. in 24-hour time","wrong_answer":"15:32","correct_answer":"15:20"}'::jsonb, 'Adds 12 to every number in the time.', 'A time with the minutes changed.', 'The minutes never change: only the hour gets 12 added.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.CONVERT_12_24.M_PM_ON_24H', 'MATH.G6.MEASUR.TIME.CONVERT_12_24', 'Writes a 24-hour time with p.m. instead of taking 12 away.', '{"question":"18:30 in 12-hour time","wrong_answer":"18:30 p.m.","correct_answer":"6:30 p.m."}'::jsonb, 'Adds p.m. without changing the hour.', 'The 24-hour number with p.m. as an option.', 'On a 12-hour clock no hour is more than 12: take 12 away, then write p.m.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.CONVERT_12_24.M_SUBTRACT_TEN', 'MATH.G6.MEASUR.TIME.CONVERT_12_24', 'Takes 10 away from a 24-hour hour to get the 12-hour time.', '{"question":"16:00 in 12-hour time","wrong_answer":"6:00 p.m.","correct_answer":"4:00 p.m."}'::jsonb, 'Drops the first digit of the hour.', 'A time two hours late as an option.', 'Take away 12, not 10: 16 - 12 = 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.TRAVEL_TIMETABLE.M_HOURS_ONLY', 'MATH.G6.MEASUR.TIME.TRAVEL_TIMETABLE', 'Takes the hours away and ignores the minutes.', '{"question":"A bus leaves at 08:40 and arrives at 11:15. How long is the journey?","wrong_answer":"3 hours","correct_answer":"2 h 35 min"}'::jsonb, 'Looks only at the hour numbers.', 'A whole number of hours as an option.', 'Count on: 08:40 to 09:00 is 20 min, 09:00 to 11:00 is 2 h, 11:00 to 11:15 is 15 min.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.TIME.TRAVEL_TIMETABLE.M_OVERNIGHT_SUBTRACTED', 'MATH.G6.MEASUR.TIME.TRAVEL_TIMETABLE', 'For an overnight journey takes the arrival time from the departure time.', '{"question":"A bus leaves at 21:30 and arrives at 05:00 the next day. How long is the journey?","wrong_answer":"16 h 30 min (21:30 - 05:00)","correct_answer":"7 h 30 min"}'::jsonb, 'Subtracts the smaller time from the larger.', 'The other part of the day as an option.', 'Count on to midnight (2 h 30 min), then from midnight to 05:00 (5 h).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.PREPARE_BUDGET.M_ADD_INCOME_TO_SPENDING', 'MATH.G6.MEASUR.MONEY.PREPARE_BUDGET', 'Adds income and spending to find the balance.', '{"question":"Income 5,000, spending 3,200: balance?","wrong_answer":"8,200","correct_answer":"1,800"}'::jsonb, 'Adds all the numbers in the table.', 'Total of all amounts.', 'Balance is what is left after spending.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.PREPARE_BUDGET.M_ITEM_LEFT_OUT', 'MATH.G6.MEASUR.MONEY.PREPARE_BUDGET', 'Leaves out an item when totalling the spending.', '{"question":"Four items in a budget table","wrong_answer":"total of three items","correct_answer":"total of four"}'::jsonb, 'Loses track of a row.', 'Total missing one item.', 'Tick each item off as it is added.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.BUYING_SELLING_PRICE.M_SELLING_FOR_BUYING', 'MATH.G6.MEASUR.MONEY.BUYING_SELLING_PRICE', 'Takes the selling price as the buying price.', '{"question":"A trader sells a bag for 1,200 making profit of 200: buying price?","wrong_answer":"1,200","correct_answer":"1,000"}'::jsonb, 'Does not tell which price is which.', 'Selling price as option.', 'Cost is what the trader paid; price is what the customer pays.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.BUYING_SELLING_PRICE.M_ADD_LOSS', 'MATH.G6.MEASUR.MONEY.BUYING_SELLING_PRICE', 'Adds a loss to the buying price to find the selling price.', '{"question":"Bought at 800, sold at a loss of 150: selling price?","wrong_answer":"950","correct_answer":"650"}'::jsonb, 'Does not see that a loss lowers the price.', 'Wrong direction.', 'A loss means the shop got less than it paid.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.PROFIT_FROM_SALES.M_PROFIT_PER_ITEM_VS_TOTAL', 'MATH.G6.MEASUR.MONEY.PROFIT_FROM_SALES', 'Gives the profit on one item when asked for the profit on all items.', '{"question":"12 mangoes bought for 5 each, sold for 8 each: total profit?","wrong_answer":"3","correct_answer":"36"}'::jsonb, 'Does not multiply by the number of items.', 'Profit on one item.', 'Total selling less total cost.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.PROFIT_FROM_SALES.M_SELLING_LESS_BUYING_REVERSED', 'MATH.G6.MEASUR.MONEY.PROFIT_FROM_SALES', 'Subtracts selling price from buying price and gives a negative or reversed answer.', '{"question":"Bought at 500, sold at 650: profit?","wrong_answer":"-150 or 1,150","correct_answer":"150"}'::jsonb, 'Subtracts in the order written.', 'Reversed subtraction.', 'The bigger price comes first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.LOSS_FROM_SALES.M_LOSS_AS_PROFIT', 'MATH.G6.MEASUR.MONEY.LOSS_FROM_SALES', 'Calls the difference a profit even when the selling price is lower.', '{"question":"Bought at 900, sold at 700: profit or loss?","wrong_answer":"profit of 200","correct_answer":"loss of 200"}'::jsonb, 'Only knows the word profit.', 'Wording that suggests profit.', 'Compare the two prices; if selling is less there is a loss.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.LOSS_FROM_SALES.M_SPOILT_GOODS_IGNORED', 'MATH.G6.MEASUR.MONEY.LOSS_FROM_SALES', 'Ignores spoilt goods that bring in no money when working out the loss.', '{"question":"Buys 20 tomatoes, 4 spoilt, sells the rest","wrong_answer":"sells all 20","correct_answer":"sells 16"}'::jsonb, 'Counts all items as sold.', 'Revenue from all items.', 'Count how many were actually sold.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.TYPES_OF_TAXES.M_VAT_ON_PAY', 'MATH.G6.MEASUR.MONEY.TYPES_OF_TAXES', 'Says VAT is taken from workers'' pay (confuses with PAYE).', '{"question":"Which tax is taken from a worker''s pay?","wrong_answer":"VAT","correct_answer":"PAYE"}'::jsonb, 'Mixes up the names.', 'Pay-related question.', 'VAT is on things bought; PAYE is on pay earned.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.TYPES_OF_TAXES.M_TAX_PERCENT_OFF_THE_PRICE', 'MATH.G6.MEASUR.MONEY.TYPES_OF_TAXES', 'Takes the tax off the price instead of adding it.', '{"question":"Price 1,000 plus 16% VAT","wrong_answer":"840","correct_answer":"1,160"}'::jsonb, 'Treats tax like a discount.', 'Discounted amount as option.', 'VAT is added to the price paid.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.PREPARE_BUDGET.M_OVER_BUDGET_AS_LEFT', 'MATH.G6.MEASUR.MONEY.PREPARE_BUDGET', 'When spending is more than income, takes the smaller from the larger and says money is left.', '{"question":"Income Ksh 4,000, planned spending Ksh 4,600. What is the balance?","wrong_answer":"Ksh 600 left","correct_answer":"Over budget by Ksh 600 (spending is Ksh 600 more than income)"}'::jsonb, 'Always subtracts the smaller number from the larger.', 'A balance of money left as an option.', 'Ask: is there enough money for everything on the list? Compare the two totals first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.PREPARE_BUDGET.M_UNIT_PRICE_FOR_LINE', 'MATH.G6.MEASUR.MONEY.PREPARE_BUDGET', 'Writes the price of one unit as the cost of a budget line that buys several.', '{"question":"Budget line: 3 kg of sugar at Ksh 180 per kg. Cost?","wrong_answer":"Ksh 180","correct_answer":"Ksh 540"}'::jsonb, 'Copies the price without reading the quantity.', 'The unit price as the line cost.', 'Read each line as "how many, at what price": 3 x 180.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.BUYING_SELLING_PRICE.M_PROFIT_TAKEN_OFF_FOR_SELLING', 'MATH.G6.MEASUR.MONEY.BUYING_SELLING_PRICE', 'Takes the profit away from the buying price to find the selling price.', '{"question":"Bought at Ksh 600 and sold at a profit of Ksh 150. Selling price?","wrong_answer":"Ksh 450","correct_answer":"Ksh 750"}'::jsonb, 'Not sure whether profit is added or taken away.', 'The buying price minus the profit as an option.', 'A profit means the trader got more than they paid: selling price = buying price + profit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.BUYING_SELLING_PRICE.M_LOSS_TAKEN_OFF_FOR_BUYING', 'MATH.G6.MEASUR.MONEY.BUYING_SELLING_PRICE', 'Takes the loss away from the selling price to find the buying price.', '{"question":"Sold for Ksh 650 at a loss of Ksh 150. Buying price?","wrong_answer":"Ksh 500","correct_answer":"Ksh 800"}'::jsonb, 'Not sure which way the loss goes.', 'The selling price minus the loss as an option.', 'A loss means the trader paid more than they got: buying price = selling price + loss.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.PROFIT_FROM_SALES.M_PROFIT_IS_SELLING_PRICE', 'MATH.G6.MEASUR.MONEY.PROFIT_FROM_SALES', 'Gives the selling price as the profit.', '{"question":"Bought at Ksh 500, sold at Ksh 650. Profit?","wrong_answer":"Ksh 650","correct_answer":"Ksh 150"}'::jsonb, 'Thinks all the money received is profit.', 'The selling price as an option.', 'The trader first gets back the Ksh 500 paid; only what is above it is profit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.PROFIT_FROM_SALES.M_BULK_COST_AGAINST_ONE_PRICE', 'MATH.G6.MEASUR.MONEY.PROFIT_FROM_SALES', 'Compares the cost of a whole crate with the price of one item.', '{"question":"A crate of 30 eggs costs Ksh 360. Each egg is sold for Ksh 15. Profit on the crate?","wrong_answer":"Ksh 345 (360 - 15)","correct_answer":"Ksh 90 (30 x 15 = 450, 450 - 360)"}'::jsonb, 'Subtracts the two prices it sees without matching what each is for.', 'The difference between the crate cost and one price.', 'Make both totals for the same thing: the money from all 30 eggs, then take away the crate cost.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.LOSS_FROM_SALES.M_EXTRA_COSTS_IGNORED', 'MATH.G6.MEASUR.MONEY.LOSS_FROM_SALES', 'Leaves out other costs such as transport when deciding profit or loss.', '{"question":"Goods bought for Ksh 2,000, transport Ksh 300, sold for Ksh 2,100. Profit or loss?","wrong_answer":"Profit of Ksh 100","correct_answer":"Loss of Ksh 200"}'::jsonb, 'Compares only the two prices named buying and selling.', 'A profit when the extra cost makes it a loss.', 'Add every cost first: 2,000 + 300 = 2,300 spent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.LOSS_FROM_SALES.M_LOSS_ON_ONE_ITEM', 'MATH.G6.MEASUR.MONEY.LOSS_FROM_SALES', 'Gives the loss on one item when the loss on all of them is asked.', '{"question":"10 pens bought at Ksh 30 each and sold at Ksh 25 each. Total loss?","wrong_answer":"Ksh 5","correct_answer":"Ksh 50"}'::jsonb, 'Stops after working out one item.', 'The loss on one item as an option.', 'Read the question again: all 10 pens. Multiply the loss on one by 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.TYPES_OF_TAXES.M_DUTY_ON_LOCAL_GOODS', 'MATH.G6.MEASUR.MONEY.TYPES_OF_TAXES', 'Believes import duty is charged on goods made and sold in Kenya.', '{"question":"Import duty is charged on?","wrong_answer":"goods made and sold in Kenya","correct_answer":"goods brought into Kenya from other countries"}'::jsonb, 'Mixes up the names of the taxes.', 'Local goods among the choices.', '"Import" means bringing in: the duty is paid when goods come into the country.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.MEASUR.MONEY.TYPES_OF_TAXES.M_TAX_AS_TOTAL', 'MATH.G6.MEASUR.MONEY.TYPES_OF_TAXES', 'Gives the tax as the total price, or the total as the tax.', '{"question":"A radio costs Ksh 1,000 plus 16% VAT. What is the total price?","wrong_answer":"Ksh 160","correct_answer":"Ksh 1,160"}'::jsonb, 'Works out the tax and stops.', 'The tax on its own as the total.', 'Read the question: the total is the price and the tax together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.LINES.PARALLEL_LINES.M_SAME_DIRECTION_ENOUGH', 'MATH.G6.GEOMET.LINES.PARALLEL_LINES', 'Believes any two lines pointing the same way are parallel, even if they are not the same distance apart.', '{"question":"Two lines closer together at one end","wrong_answer":"parallel","correct_answer":"not parallel"}'::jsonb, 'Only looks at direction.', 'A pair of lines getting closer.', 'Measure the gap at both ends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.LINES.PARALLEL_LINES.M_PARALLEL_MEANS_HORIZONTAL', 'MATH.G6.GEOMET.LINES.PARALLEL_LINES', 'Believes parallel lines must be horizontal.', '{"question":"Two slanting rails","wrong_answer":"not parallel (not horizontal)","correct_answer":"parallel"}'::jsonb, 'Examples in books are drawn level.', 'Slanted parallel pair.', 'Turn the page and see that the pair stays parallel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.LINES.BISECT_LINES.M_BISECT_MEANS_CUT_ANYWHERE', 'MATH.G6.GEOMET.LINES.BISECT_LINES', 'Believes bisecting is cutting a line anywhere.', '{"question":"A 12 cm line is bisected: length of each part?","wrong_answer":"5 cm and 7 cm","correct_answer":"6 cm and 6 cm"}'::jsonb, 'Does not know that bisect means equal.', 'Two unequal parts as option.', 'Fold the line so that the ends meet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.LINES.BISECT_LINES.M_HALF_OF_WRONG_LENGTH', 'MATH.G6.GEOMET.LINES.BISECT_LINES', 'Halves the wrong number or gives the whole length as the answer.', '{"question":"A 18 cm line bisected","wrong_answer":"18 cm","correct_answer":"9 cm"}'::jsonb, 'Does not apply the halving.', 'Whole length as option.', 'Two equal parts means share the length by 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.LINES.PERPENDICULAR_LINES.M_PERPENDICULAR_AS_STRAIGHT', 'MATH.G6.GEOMET.LINES.PERPENDICULAR_LINES', 'Believes perpendicular lines make a straight line (180 degrees).', '{"question":"Angle between perpendicular lines?","wrong_answer":"180 degrees","correct_answer":"90 degrees"}'::jsonb, 'Mixes angles on a straight line and right angles.', 'Option 180 degrees.', 'Check the corner of a book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.LINES.PERPENDICULAR_LINES.M_PERPENDICULAR_AS_VERTICAL', 'MATH.G6.GEOMET.LINES.PERPENDICULAR_LINES', 'Believes perpendicular lines must be one horizontal and one vertical.', '{"question":"Two lines slanted, meeting at a right angle","wrong_answer":"not perpendicular","correct_answer":"perpendicular"}'::jsonb, 'Only knows the book-corner picture.', 'Tilted perpendicular pair.', 'Turn the page: the right angle stays a right angle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.LINES.PARALLEL_LINES.M_SAME_LENGTH_NEEDED', 'MATH.G6.GEOMET.LINES.PARALLEL_LINES', 'Believes parallel lines must be the same length or start and end together.', '{"question":"One line is 3 cm long and another 8 cm long, always 2 cm apart. Are they parallel?","wrong_answer":"No, they are not the same length","correct_answer":"Yes: they stay the same distance apart"}'::jsonb, 'Has mostly seen parallel lines drawn as equal pairs.', 'A no because of different lengths.', 'Parallel is about the gap, not the length: measure the gap at two places.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.LINES.PARALLEL_LINES.M_SET_SQUARE_TURNED', 'MATH.G6.GEOMET.LINES.PARALLEL_LINES', 'Turns the set square between drawing the two lines, so the lines are not parallel.', '{"question":"Wanjiku slides her set square along the ruler but turns it a little before drawing the second line. Are her lines parallel?","wrong_answer":"Yes, she used a set square","correct_answer":"No: the set square must slide without turning"}'::jsonb, 'Thinks using the tool is enough, whatever the movement.', 'A yes because a set square was used.', 'Hold the ruler still and slide the set square along it without turning it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.LINES.BISECT_LINES.M_BISECTOR_ANY_ANGLE', 'MATH.G6.GEOMET.LINES.BISECT_LINES', 'Believes any line through the midpoint is the perpendicular bisector.', '{"question":"A line cuts AB at its midpoint at 60 degrees. Is it the perpendicular bisector of AB?","wrong_answer":"Yes, it goes through the middle","correct_answer":"No: the perpendicular bisector meets AB at 90 degrees"}'::jsonb, 'Remembers the "middle" and forgets the right angle.', 'A yes for a slanting line through the midpoint.', 'Check two things: equal halves, and a right angle at the midpoint.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.LINES.BISECT_LINES.M_ARCS_TOO_SMALL', 'MATH.G6.GEOMET.LINES.BISECT_LINES', 'Uses a compass radius of half the line or less, so the arcs from the two ends do not meet.', '{"question":"Arcs of radius 3 cm are drawn from each end of an 8 cm line. Where do they cross?","wrong_answer":"At the midpoint, above and below","correct_answer":"They do not meet: the radius must be more than half of the line (more than 4 cm)"}'::jsonb, 'Opens the compasses to any size.', 'A crossing point that cannot exist.', 'Open the compasses to more than half the line, and keep the same opening for both ends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.LINES.PERPENDICULAR_LINES.M_MUST_CROSS', 'MATH.G6.GEOMET.LINES.PERPENDICULAR_LINES', 'Believes perpendicular lines must cross, so a corner (L) or a T is not perpendicular.', '{"question":"Are the two lines of a capital L perpendicular?","wrong_answer":"No, they do not cross","correct_answer":"Yes: they meet at a right angle"}'::jsonb, 'Has seen perpendicular lines drawn as a cross.', 'A no for lines that meet at a corner.', 'Perpendicular means meeting at a right angle; they can meet at an end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.LINES.PERPENDICULAR_LINES.M_RIGHT_ANGLE_BY_EYE', 'MATH.G6.GEOMET.LINES.PERPENDICULAR_LINES', 'Calls lines perpendicular because they look square, without checking the angle.', '{"question":"Two lines meet at 85 degrees. Are they perpendicular?","wrong_answer":"Yes, it looks like a right angle","correct_answer":"No: perpendicular means exactly 90 degrees"}'::jsonb, 'Judges by eye.', 'A yes for an angle close to 90.', 'Check with the corner of a set square or a protractor.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.ANGLES_STRAIGHT_LINE_IDENTIFY.M_ANY_TWO_ANGLES', 'MATH.G6.GEOMET.ANGLES.ANGLES_STRAIGHT_LINE_IDENTIFY', 'Believes any two angles drawn near each other are on a straight line.', '{"question":"Which pair of angles lie on a straight line?","wrong_answer":"two neighbouring angles of an L-shape","correct_answer":"two angles that meet along a line"}'::jsonb, 'Only checks that the angles touch.', 'Neighbouring angles that make a corner.', 'Check the outer arms lie along one line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.ANGLES_STRAIGHT_LINE_IDENTIFY.M_OBTUSE_AS_ACUTE', 'MATH.G6.GEOMET.ANGLES.ANGLES_STRAIGHT_LINE_IDENTIFY', 'Calls angles by size looks rather than by the 90 degree rule.', '{"question":"Is an angle of 120 degrees acute or obtuse?","wrong_answer":"acute","correct_answer":"obtuse"}'::jsonb, 'Thinks all small-looking angles on paper are acute.', 'Angle just over 90 degrees.', 'Compare with the corner of a book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.MEASURE_ANGLES_PROTRACTOR.M_WRONG_SCALE', 'MATH.G6.GEOMET.ANGLES.MEASURE_ANGLES_PROTRACTOR', 'Reads the wrong scale of the protractor, giving the supplement of the angle.', '{"question":"An acute angle starting on the inner zero is read from the outer scale","wrong_answer":"130 degrees","correct_answer":"50 degrees"}'::jsonb, 'Starts at the nearer number, not at zero on the baseline.', 'Supplement as option.', 'Ask: is the angle smaller or bigger than a right angle, then choose the reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.MEASURE_ANGLES_PROTRACTOR.M_DIFFERENCE_AS_SUM', 'MATH.G6.GEOMET.ANGLES.MEASURE_ANGLES_PROTRACTOR', 'Adds two protractor readings to find the angle between two arms.', '{"question":"Arms at 35 and 110 degrees: angle between?","wrong_answer":"145 degrees","correct_answer":"75 degrees"}'::jsonb, 'Adds all the numbers it can see.', 'Sum as an option.', 'The angle between is the difference of the two readings.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.SUM_ANGLES_STRAIGHT_LINE.M_NINETY_NOT_180', 'MATH.G6.GEOMET.ANGLES.SUM_ANGLES_STRAIGHT_LINE', 'Takes 90 degrees as the total on a straight line.', '{"question":"Angle 40 on a line, other angle?","wrong_answer":"50 degrees","correct_answer":"140 degrees"}'::jsonb, 'Confuses a right angle and a straight angle.', 'The complement of the angle.', 'A straight line is half a turn: 180 degrees.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.SUM_ANGLES_STRAIGHT_LINE.M_THREE_HUNDRED_SIXTY', 'MATH.G6.GEOMET.ANGLES.SUM_ANGLES_STRAIGHT_LINE', 'Takes 360 degrees as the total on a straight line.', '{"question":"Angles of 100 and 50 degrees on a line, third angle?","wrong_answer":"210 degrees","correct_answer":"30 degrees"}'::jsonb, 'Mixes angles at a point with angles on a line.', 'The 360-based answer.', 'A full turn is 360 degrees but only half a turn is on a line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.ANGLE_SUM_RECT_TRIANGLE.M_TRIANGLE_360', 'MATH.G6.GEOMET.ANGLES.ANGLE_SUM_RECT_TRIANGLE', 'Believes the angles of a triangle add up to 360 degrees.', '{"question":"Angles 70 and 50: third angle of a triangle?","wrong_answer":"240 degrees","correct_answer":"60 degrees"}'::jsonb, 'Remembers the rectangle total.', '360-based answer.', 'Tear off the corners and put them on a straight line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.ANGLE_SUM_RECT_TRIANGLE.M_RECTANGLE_180', 'MATH.G6.GEOMET.ANGLES.ANGLE_SUM_RECT_TRIANGLE', 'Believes the angles of a rectangle add up to 180 degrees.', '{"question":"Sum of the angles of a rectangle?","wrong_answer":"180 degrees","correct_answer":"360 degrees"}'::jsonb, 'Remembers the triangle total.', 'Option 180 degrees.', 'Four right angles are 360 degrees.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.CONSTRUCT_TRIANGLES.M_ISOSCELES_THREE_EQUAL', 'MATH.G6.GEOMET.ANGLES.CONSTRUCT_TRIANGLES', 'Believes an isosceles triangle has three equal sides.', '{"question":"How many equal sides has an isosceles triangle?","wrong_answer":"3","correct_answer":"2"}'::jsonb, 'Mixes isosceles with equilateral.', 'Option 3.', 'Fold an isosceles triangle on its line of symmetry.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.CONSTRUCT_TRIANGLES.M_EQUILATERAL_ANGLE_90', 'MATH.G6.GEOMET.ANGLES.CONSTRUCT_TRIANGLES', 'Believes each angle of an equilateral triangle is 90 degrees or 45 degrees.', '{"question":"Each angle of an equilateral triangle?","wrong_answer":"90 degrees","correct_answer":"60 degrees"}'::jsonb, 'Takes the right angle as typical.', 'Option 90 degrees.', 'Three equal angles in 180 degrees are 180 shared by 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.INTERIOR_ANGLES_TRIANGLES.M_BASE_ANGLES_NOT_EQUAL', 'MATH.G6.GEOMET.ANGLES.INTERIOR_ANGLES_TRIANGLES', 'Does not use that the base angles of an isosceles triangle are equal.', '{"question":"Apex angle 40 degrees, isosceles: base angle?","wrong_answer":"140 degrees","correct_answer":"70 degrees"}'::jsonb, 'Gives the rest of 180 as one angle.', 'Answer 140 degrees.', 'Share the 140 degrees between the two equal angles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.INTERIOR_ANGLES_TRIANGLES.M_RIGHT_ANGLED_OTHER_90', 'MATH.G6.GEOMET.ANGLES.INTERIOR_ANGLES_TRIANGLES', 'Gives 90 degrees as each of the other angles of a right-angled triangle, or the sum 180 for one.', '{"question":"A right-angled triangle has an angle of 35 degrees as well. Third angle?","wrong_answer":"90 degrees (the right angle given again)","correct_answer":"55 degrees"}'::jsonb, 'Mixes up the right angle with the missing one.', 'Answer 90 degrees.', 'Subtract both known angles from 180.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.ANGLE_SUM_RECT_TRIANGLE.M_SUBTRACT_ONE_ANGLE_ONLY', 'MATH.G6.GEOMET.ANGLES.ANGLE_SUM_RECT_TRIANGLE', 'Subtracts only one of the two known angles from 180 degrees to find the third angle of a triangle.', '{"question":"Angles 60 and 70: third angle?","wrong_answer":"120 degrees","correct_answer":"50 degrees"}'::jsonb, 'Forgets the second known angle.', 'Answer from one subtraction.', 'Add the known angles first, then subtract the total from 180.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.ANGLE_SUM_RECT_TRIANGLE.M_ONE_CORNER_ONLY', 'MATH.G6.GEOMET.ANGLES.ANGLE_SUM_RECT_TRIANGLE', 'Gives the size of one corner (90 degrees) as the sum of the angles of a rectangle.', '{"question":"Sum of the angles of a rectangle?","wrong_answer":"90 degrees","correct_answer":"360 degrees"}'::jsonb, 'Thinks of a single right angle.', 'Option 90 degrees.', 'Count the corners: four right angles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.CONSTRUCT_TRIANGLES.M_TRIANGLE_NAMES_MIXED', 'MATH.G6.GEOMET.ANGLES.CONSTRUCT_TRIANGLES', 'Mixes up the names equilateral, isosceles and right-angled.', '{"question":"A triangle with three equal sides is called?","wrong_answer":"isosceles","correct_answer":"equilateral"}'::jsonb, 'Learns the names as a list without the meaning.', 'Names of the other triangles as options.', 'Say what each name tells: equi means equal, a right angle is 90 degrees.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.ANGLES_STRAIGHT_LINE_IDENTIFY.M_LONG_ARMS_BIGGER', 'MATH.G6.GEOMET.ANGLES.ANGLES_STRAIGHT_LINE_IDENTIFY', 'Believes an angle with longer arms is a bigger angle.', '{"question":"Two angles of 40 degrees are drawn, one with arms of 3 cm and one with arms of 8 cm. Which angle is bigger?","wrong_answer":"the one with 8 cm arms","correct_answer":"They are equal"}'::jsonb, 'Judges an angle by how much space the drawing takes.', 'The angle with longer arms as an option.', 'An angle is the amount of turn: lay one angle on the other and see the arms line up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.ANGLES_STRAIGHT_LINE_IDENTIFY.M_ONLY_TWO_ON_A_LINE', 'MATH.G6.GEOMET.ANGLES.ANGLES_STRAIGHT_LINE_IDENTIFY', 'Believes only two angles can lie on a straight line at a point.', '{"question":"Three angles meet at a point on a straight line. Do all three lie on the straight line?","wrong_answer":"No, only two angles can","correct_answer":"Yes: together they make the straight angle"}'::jsonb, 'Has seen only pairs of angles on a line.', 'A no for three angles.', 'Count every angle between the two halves of the line: there can be two, three or more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.MEASURE_ANGLES_PROTRACTOR.M_ZERO_NOT_ON_ARM', 'MATH.G6.GEOMET.ANGLES.MEASURE_ANGLES_PROTRACTOR', 'Reads where the second arm points without lining zero up with the first arm.', '{"question":"One arm of an angle lies on 20 on the protractor scale (not on 0). The other arm points to 85. What is the angle?","wrong_answer":"85 degrees","correct_answer":"65 degrees"}'::jsonb, 'Reads the number at the second arm only.', 'The reading at the second arm as an option.', 'Put the 0 line on one arm, or take the smaller reading from the larger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.MEASURE_ANGLES_PROTRACTOR.M_EDGE_ON_VERTEX', 'MATH.G6.GEOMET.ANGLES.MEASURE_ANGLES_PROTRACTOR', 'Puts the edge or the end of the protractor on the vertex instead of the centre mark.', '{"question":"Which part of the protractor goes on the vertex (corner) of the angle?","wrong_answer":"the edge (or the end) of the protractor","correct_answer":"the centre mark on the baseline"}'::jsonb, 'Treats the protractor like a ruler that starts at its end.', 'The edge of the protractor as an option.', 'Find the small centre mark on the straight edge and put it exactly on the corner.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.SUM_ANGLES_STRAIGHT_LINE.M_MULTIPLE_HALVED', 'MATH.G6.GEOMET.ANGLES.SUM_ANGLES_STRAIGHT_LINE', 'When one angle on a line is a multiple of the other, halves 180 instead of sharing it in the right parts.', '{"question":"Two angles lie on a straight line and one is twice the other. What is the smaller angle?","wrong_answer":"90 degrees","correct_answer":"60 degrees"}'::jsonb, 'Shares 180 into two equal parts out of habit.', 'Half of 180 as an option.', 'Draw it as parts: the small angle is 1 part, the big one 2 parts, so 3 parts make 180.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.SUM_ANGLES_STRAIGHT_LINE.M_ONE_ANGLE_SUBTRACTED_LINE', 'MATH.G6.GEOMET.ANGLES.SUM_ANGLES_STRAIGHT_LINE', 'With three angles on a line, takes only one of the known angles from 180.', '{"question":"Angles of 100 and 50 degrees and an unknown angle lie on a straight line. What is the unknown angle?","wrong_answer":"80 degrees","correct_answer":"30 degrees"}'::jsonb, 'Stops after one subtraction.', 'An answer that misses one known angle.', 'Add the known angles first: 100 + 50 = 150, then 180 - 150.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.CONSTRUCT_TRIANGLES.M_RIGHT_NOT_ISOSCELES', 'MATH.G6.GEOMET.ANGLES.CONSTRUCT_TRIANGLES', 'Believes a right-angled triangle cannot also be isosceles.', '{"question":"Can a triangle be both right-angled and isosceles?","wrong_answer":"No, it is one or the other","correct_answer":"Yes: its angles are 90, 45 and 45 degrees"}'::jsonb, 'Thinks each triangle has only one name.', 'A no among the choices.', 'Fold a square along its diagonal: each half has a right angle and two equal sides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.INTERIOR_ANGLES_TRIANGLES.M_GIVEN_ANGLE_TAKEN_AS_APEX', 'MATH.G6.GEOMET.ANGLES.INTERIOR_ANGLES_TRIANGLES', 'Treats a given base angle of an isosceles triangle as the angle at the top.', '{"question":"An isosceles triangle has a base angle of 50 degrees. What is the angle at the top?","wrong_answer":"65 degrees ((180 - 50) / 2)","correct_answer":"80 degrees (180 - 50 - 50)"}'::jsonb, 'Uses the apex method on a base angle.', 'The answer from halving 180 minus the given angle.', 'Mark the two equal angles first: both base angles are 50, so the top is 180 - 100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.ANGLES.INTERIOR_ANGLES_TRIANGLES.M_BIG_EQUILATERAL_BIG_ANGLES', 'MATH.G6.GEOMET.ANGLES.INTERIOR_ANGLES_TRIANGLES', 'Believes a bigger equilateral triangle has bigger angles.', '{"question":"An equilateral triangle has sides of 10 cm. What is each angle?","wrong_answer":"more than 60 degrees, because the sides are long","correct_answer":"60 degrees"}'::jsonb, 'Links the size of the angles to the length of the sides.', 'An angle bigger than 60 as an option.', 'Three equal angles always share 180: 180 / 3 = 60, for any size.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.3_D_OBJECTS.CUBOID_CUBE_PARTS.M_EDGES_AS_FACES', 'MATH.G6.GEOMET.3_D_OBJECTS.CUBOID_CUBE_PARTS', 'Counts edges where faces are asked (or the reverse).', '{"question":"Faces of a cube?","wrong_answer":"12","correct_answer":"6"}'::jsonb, 'Mixes the words.', 'Options 8 and 12.', 'Hold a box: colour each flat surface for faces, trace each edge.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.3_D_OBJECTS.CUBOID_CUBE_PARTS.M_HIDDEN_EDGES_MISSED', 'MATH.G6.GEOMET.3_D_OBJECTS.CUBOID_CUBE_PARTS', 'Counts only the edges that can be seen in a drawing, giving 9 instead of 12.', '{"question":"Edges of a cuboid drawn on paper","wrong_answer":"9","correct_answer":"12"}'::jsonb, 'Does not count hidden edges.', 'Option 9.', 'Use a real box and count 4 + 4 + 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.3_D_OBJECTS.CYLINDER_PARTS.M_CYLINDER_THREE_FACES_ALL_FLAT', 'MATH.G6.GEOMET.3_D_OBJECTS.CYLINDER_PARTS', 'Counts the curved surface as a flat face or says it has no faces at all.', '{"question":"How many flat faces has a cylinder?","wrong_answer":"3","correct_answer":"2"}'::jsonb, 'Counts the curved side as another flat face.', 'Option 3.', 'Roll a tin: the side rolls, so it is not flat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.3_D_OBJECTS.CYLINDER_PARTS.M_CYLINDER_HAS_VERTICES', 'MATH.G6.GEOMET.3_D_OBJECTS.CYLINDER_PARTS', 'Says a cylinder has vertices where the flat and curved parts meet.', '{"question":"Vertices of a cylinder?","wrong_answer":"2","correct_answer":"0"}'::jsonb, 'Treats a curved edge as a corner.', 'Option 2.', 'Run a finger round the edge: no point.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.3_D_OBJECTS.PLANE_FIGURES_IN_SOLIDS.M_FACE_AS_SOLID', 'MATH.G6.GEOMET.3_D_OBJECTS.PLANE_FIGURES_IN_SOLIDS', 'Names a 3-D solid where a plane figure is asked (cube for square).', '{"question":"Shape of one face of a cube?","wrong_answer":"cube","correct_answer":"square"}'::jsonb, 'Does not separate flat from solid.', 'A solid name as an option.', 'Trace a face on paper and name the drawing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.3_D_OBJECTS.PLANE_FIGURES_IN_SOLIDS.M_CYLINDER_FACE_OVAL', 'MATH.G6.GEOMET.3_D_OBJECTS.PLANE_FIGURES_IN_SOLIDS', 'Names the flat end of a cylinder as an oval or a sphere.', '{"question":"Shape of the flat end of a tin?","wrong_answer":"oval","correct_answer":"circle"}'::jsonb, 'Draws the circle in perspective.', 'Oval as an option.', 'Trace the end of a tin on paper.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.3_D_OBJECTS.CUBOID_CUBE_PARTS.M_HIDDEN_VERTEX_MISSED', 'MATH.G6.GEOMET.3_D_OBJECTS.CUBOID_CUBE_PARTS', 'Counts only the vertices that can be seen in a drawing.', '{"question":"How many vertices has the cube in this drawing?","wrong_answer":"7","correct_answer":"8"}'::jsonb, 'Counts what the picture shows and forgets the corner at the back.', 'The count of visible vertices as an option.', 'Count on a real box, marking each corner with chalk: 4 on top, 4 at the bottom.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.3_D_OBJECTS.CUBOID_CUBE_PARTS.M_WIRE_ONE_OF_EACH', 'MATH.G6.GEOMET.3_D_OBJECTS.CUBOID_CUBE_PARTS', 'Adds one length, one width and one height for the wire of all the edges of a cuboid.', '{"question":"A cuboid frame is 5 cm by 3 cm by 2 cm. What length of wire makes all its edges?","wrong_answer":"10 cm","correct_answer":"40 cm (4 x 5 + 4 x 3 + 4 x 2)"}'::jsonb, 'Counts one edge of each length, not four.', 'The sum of the three lengths as an option.', 'Run a finger along every edge of a box: there are 4 edges of each length.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.3_D_OBJECTS.CYLINDER_PARTS.M_CURVED_SURFACE_NOT_COUNTED', 'MATH.G6.GEOMET.3_D_OBJECTS.CYLINDER_PARTS', 'Counts only the flat faces when asked for all the surfaces of a cylinder.', '{"question":"How many surfaces does a cylinder have in all?","wrong_answer":"2","correct_answer":"3 (2 flat faces and 1 curved surface)"}'::jsonb, 'Thinks only flat parts count as surfaces.', 'Only the flat faces as an option.', 'Wrap paper round a tin: the curved part is a surface too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.3_D_OBJECTS.CYLINDER_PARTS.M_SIDE_LINES_AS_EDGES', 'MATH.G6.GEOMET.3_D_OBJECTS.CYLINDER_PARTS', 'Counts the two straight side lines of a drawing as edges of the cylinder.', '{"question":"How many edges does a cylinder have, and what kind?","wrong_answer":"2 straight edges down the sides (from the drawing)","correct_answer":"2 curved edges, one round each end"}'::jsonb, 'Reads the outline of the drawing as edges.', 'Straight edges as an option.', 'Run a finger down the side of a tin: there is no edge, it is smooth. The edges are where the flat ends meet the curve.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.3_D_OBJECTS.PLANE_FIGURES_IN_SOLIDS.M_CUBOID_ALL_SQUARES', 'MATH.G6.GEOMET.3_D_OBJECTS.PLANE_FIGURES_IN_SOLIDS', 'Says all the faces of a cuboid are squares.', '{"question":"What shape are the faces of a chalk box (a cuboid)?","wrong_answer":"squares","correct_answer":"rectangles (two of them may be squares)"}'::jsonb, 'Mixes up the cube and the cuboid.', 'Squares for a cuboid as an option.', 'Measure the sides of a face: a square has all four sides equal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.GEOMET.3_D_OBJECTS.PLANE_FIGURES_IN_SOLIDS.M_PYRAMID_ALL_TRIANGLES', 'MATH.G6.GEOMET.3_D_OBJECTS.PLANE_FIGURES_IN_SOLIDS', 'Says all the faces of a square-based pyramid are triangles.', '{"question":"What are the faces of a square-based pyramid?","wrong_answer":"5 triangles","correct_answer":"4 triangles and 1 square"}'::jsonb, 'Remembers a pyramid as "triangles" and forgets the base.', 'All triangles as an option.', 'Stand the pyramid on the table and look at the face it stands on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.FREQUENCY_TABLE.M_ADD_VALUES_NOT_FREQUENCIES', 'MATH.G6.DATA_H.BAR_GRAPHS.FREQUENCY_TABLE', 'Adds the values (0, 1, 2, ...) instead of the frequencies to find the number of learners.', '{"question":"Books read 0,1,2,3 with frequencies 4,6,5,2: how many learners?","wrong_answer":"6","correct_answer":"17"}'::jsonb, 'Does not see which column counts people.', 'The sum of values.', 'The frequency column says how many learners gave each answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.FREQUENCY_TABLE.M_FREQUENCY_AS_VALUE', 'MATH.G6.DATA_H.BAR_GRAPHS.FREQUENCY_TABLE', 'Reports the biggest frequency as the most common value is not found: gives the frequency instead of the value.', '{"question":"Most common number of books?","wrong_answer":"the frequency 6","correct_answer":"the value (the number of books)"}'::jsonb, 'Mixes the value and its frequency.', 'The frequency number as an option.', 'Say it in a sentence: "6 learners read 1 book".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.PICTOGRAPH.M_KEY_IGNORED', 'MATH.G6.DATA_H.BAR_GRAPHS.PICTOGRAPH', 'Counts each symbol as one even when the key gives a bigger value.', '{"question":"Each symbol stands for 5; 4 symbols","wrong_answer":"4","correct_answer":"20"}'::jsonb, 'Does not read the key.', 'The symbol count.', 'Read the key aloud before counting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.PICTOGRAPH.M_HALF_SYMBOL_AS_WHOLE', 'MATH.G6.DATA_H.BAR_GRAPHS.PICTOGRAPH', 'Counts a half symbol as a whole one.', '{"question":"Each symbol is 10; 3 and a half symbols","wrong_answer":"40","correct_answer":"35"}'::jsonb, 'Ignores the half.', 'Value of 4 symbols.', 'Half a symbol is half of the key value.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.PILING.M_PILE_HEIGHT_NOT_COUNT', 'MATH.G6.DATA_H.BAR_GRAPHS.PILING', 'Judges the most by how spread out the pile looks rather than by counting.', '{"question":"Two piles: one spread wide, one tall","wrong_answer":"the wide one","correct_answer":"the one with more objects"}'::jsonb, 'Uses the look of the pile.', 'Piles of equal count that look different.', 'Count the objects in each pile.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.PILING.M_TOTAL_OF_TALLEST_ONLY', 'MATH.G6.DATA_H.BAR_GRAPHS.PILING', 'Takes the tallest pile as the total of all piles.', '{"question":"Piles of 5, 8 and 3","wrong_answer":"8","correct_answer":"16"}'::jsonb, 'Thinks total means largest.', 'Largest pile as an option.', 'Total means all the piles together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_DRAW.M_SCALE_STEP_ONE', 'MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_DRAW', 'Draws a bar to the count of squares as if each square were one when the scale says each is 5.', '{"question":"Scale: each square is 5; frequency 20","wrong_answer":"20 squares","correct_answer":"4 squares"}'::jsonb, 'Ignores the scale.', 'Frequency as a count of squares.', 'Divide the frequency by the value of one square.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_DRAW.M_BARS_UNEVEN_OR_NO_LABELS', 'MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_DRAW', 'Draws bars of unequal width or leaves out labels on the axes.', '{"question":"What is missing from a graph without axis labels?","wrong_answer":"nothing is missing","correct_answer":"the axis labels"}'::jsonb, 'Treats the picture alone as the graph.', 'A graph with no labels.', 'Check title, labels and scale before reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_INTERPRET.M_READ_TOP_OF_BAR_WRONG_LINE', 'MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_INTERPRET', 'Reads the value at the nearest labelled line instead of where the bar ends.', '{"question":"A bar ends halfway between the lines for 10 and 20","wrong_answer":"10 or 20 (the nearer labelled line)","correct_answer":"15"}'::jsonb, 'Does not read between the lines.', 'The labelled neighbour.', 'Check the scale: what does each small square show?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_INTERPRET.M_SECOND_HIGHEST_AS_HIGHEST', 'MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_INTERPRET', 'Gives the highest bar where the second highest was asked.', '{"question":"Second highest bar?","wrong_answer":"the tallest","correct_answer":"the next tallest"}'::jsonb, 'Does not read the question carefully.', 'Tallest bar as an option.', 'Cross out the tallest bar, then find the tallest left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_INTERPRET.M_DIFFERENCE_AS_TOTAL', 'MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_INTERPRET', 'Adds two bars to find how many more one is than the other.', '{"question":"How many more chose maize than beans?","wrong_answer":"70","correct_answer":"10"}'::jsonb, 'Adds the values.', 'Sum as an option.', 'How many more means subtract.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.PILING.M_PILE_LEFT_OUT', 'MATH.G6.DATA_H.BAR_GRAPHS.PILING', 'Leaves one pile out when adding the piles to find the total.', '{"question":"Piles of 5, 8, 3 and 6","wrong_answer":"16","correct_answer":"22"}'::jsonb, 'Loses count of the piles.', 'Total missing one pile.', 'Touch each pile once and say its number.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.FREQUENCY_TABLE.M_TALLY_GATE_AS_FOUR', 'MATH.G6.DATA_H.BAR_GRAPHS.FREQUENCY_TABLE', 'Counts a tally gate (four lines and one across) as 4, or as 6.', '{"question":"What does one gate of tally marks (four lines and one across them) stand for?","wrong_answer":"4","correct_answer":"5"}'::jsonb, 'Counts only the upright lines, or counts the cross line twice.', 'A count one off for each gate.', 'Draw the marks one by one while counting: 1, 2, 3, 4, and the fifth goes across.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.FREQUENCY_TABLE.M_MISSING_FREQUENCY_ADDED', 'MATH.G6.DATA_H.BAR_GRAPHS.FREQUENCY_TABLE', 'Adds the total to the known frequencies to find a missing one, instead of taking them away.', '{"question":"30 learners were asked. The frequencies are 8, 12 and one missing. What is the missing frequency?","wrong_answer":"50","correct_answer":"10"}'::jsonb, 'Adds every number in the question.', 'The sum as an option.', 'All the frequencies make the total: 8 + 12 + ? = 30.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.PICTOGRAPH.M_DRAW_ONE_PER_ITEM', 'MATH.G6.DATA_H.BAR_GRAPHS.PICTOGRAPH', 'Draws one symbol for each item even when the key says a symbol stands for more.', '{"question":"Each symbol stands for 5 mangoes. How many symbols show 20 mangoes?","wrong_answer":"20","correct_answer":"4"}'::jsonb, 'Does not use the key when drawing.', 'One symbol per item as an option.', 'Read the key aloud: one symbol is 5 mangoes. How many fives make 20?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.PICTOGRAPH.M_HALF_SYMBOL_AS_ONE', 'MATH.G6.DATA_H.BAR_GRAPHS.PICTOGRAPH', 'Counts a half symbol as 1 whatever the key says.', '{"question":"Each symbol stands for 10. A row has 2 and a half symbols. How many?","wrong_answer":"21","correct_answer":"25"}'::jsonb, 'Thinks a part symbol is a single item.', 'A count with the half symbol as 1.', 'Half a symbol is half of the key: half of 10 is 5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.PILING.M_UNEQUAL_OBJECTS_COMPARED', 'MATH.G6.DATA_H.BAR_GRAPHS.PILING', 'Compares piles of objects of different sizes by height.', '{"question":"Learners pile bottle tops for juice and large stones for water. The stone pile is taller. Did more learners choose water?","wrong_answer":"Yes, its pile is taller","correct_answer":"We cannot tell until we count: the objects are different sizes"}'::jsonb, 'Takes height as the count.', 'A yes from height alone.', 'Use the same kind of object for every pile, or count each pile.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_DRAW.M_UNEVEN_SCALE', 'MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_DRAW', 'Numbers the axis with uneven steps.', '{"question":"Which scale is right for a bar graph: 0, 5, 10, 20, 40 or 0, 10, 20, 30, 40?","wrong_answer":"0, 5, 10, 20, 40","correct_answer":"0, 10, 20, 30, 40"}'::jsonb, 'Writes the numbers needed for the bars, not a steady scale.', 'An uneven scale as an option.', 'Each square must stand for the same amount: count up the axis in equal steps.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_DRAW.M_SCALE_DOES_NOT_FIT', 'MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_DRAW', 'Chooses a scale that makes the tallest bar run off the grid.', '{"question":"The biggest frequency is 45 and the grid is 10 squares tall. Which scale fits: each square 1, 5 or 10?","wrong_answer":"1","correct_answer":"5 (45 needs 9 squares)"}'::jsonb, 'Uses each square as 1 out of habit.', 'A scale that is too small as an option.', 'Divide the biggest frequency by the number of squares and pick a step at least that big.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_INTERPRET.M_SQUARES_COUNTED_NOT_SCALE', 'MATH.G6.DATA_H.BAR_GRAPHS.BAR_GRAPH_INTERPRET', 'Counts the squares a bar covers instead of reading the scale.', '{"question":"Each square on the bar graph is 5. A bar is 6 squares tall. What is its value?","wrong_answer":"6","correct_answer":"30"}'::jsonb, 'Reads the height in squares, not in the scale.', 'The number of squares as an option.', 'Read the number on the axis level with the top of the bar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
